/// The continuation notice's recoverables line (issue #438 AC4).
///
/// After the over-window guard's post-run compaction, the continuation
/// notice names what the fold hid — record kinds + turn span per
/// hidden_range — and points at `compact_expand` so the continuation turn
/// can pull specific records back. E4: the enumeration caps at
/// [maxSpans] (the first and the last spans win); the full list stays in
/// the session file.
library;

import '../../session/session_record.dart';
import 'expand_tool.dart' show compactExpandToolName;
import 'projection.dart' show RecordSeqIndex, markerKindFor;

/// Builds the recoverables line for the session's hidden ranges, or the
/// empty string when nothing is hidden (classic compaction leaves no
/// hidden ranges — the notice then stays as it was).
String hiddenRecoverablesSummary(
  List<SessionRecord> entries, {
  int maxSpans = 3,
}) {
  final seqs = RecordSeqIndex(entries);
  final spans = <String>[];
  for (final hidden in entries.whereType<HiddenRangeRecord>()) {
    final nums = [for (final id in hidden.recordIds) ?seqs.seqOf(id)]..sort();
    if (nums.isEmpty) continue;
    final counts = <String, int>{};
    for (final id in hidden.recordIds) {
      // Issue #673: after a windowed resume an id may have slid out of the
      // resident set — no seq. Skip it; the raw `!` here killed the whole
      // continuation with "Null check operator used on a null value".
      final seq = seqs.seqOf(id);
      final record = seq == null ? null : seqs.recordAt(seq);
      if (record == null) continue;
      final kind = markerKindFor(record);
      counts[kind] = (counts[kind] ?? 0) + 1;
    }
    final kinds = [
      for (final e in counts.entries) '${e.key}×${e.value}',
    ].join(' ');
    spans.add('records ${nums.first}–${nums.last} ($kinds)');
  }
  if (spans.isEmpty) return '';
  final shown = spans.length <= maxSpans
      ? spans
      : [...spans.take(maxSpans - 1), spans.last];
  final more = spans.length - shown.length;
  final tail = more > 0
      ? ' · +$more more — the full list is in the session file'
      : '';
  return 'Hidden by compaction (recoverable via $compactExpandToolName): '
      '${shown.join(' · ')}$tail';
}

/// Auto-compaction loop shared by the CLI [AgentCli] and the Flutter
/// [AgentService]. Single source of truth for:
///
/// - **smol → main fallback**: when the `smol` summarizer fails (rate
///   limit, 403, etc.) and points at a different model/endpoint than the
///   main chain, retry once with the main stream. If `smol == main`,
///   skip the fallback (it would just re-trigger the same 403).
/// - **Transient retry**: 5xx HTTP, `connection closed/reset/aborted`,
///   `socket exception`, `stream closed` — up to 3 attempts with
///   1s/2s backoff. Hard refusals (`usage limit`, `429`, validation,
///   auth) fail-fast — retrying burns the same quota twice.
/// - **Multi-pass**: when the post-compaction transcript still exceeds
///   the window (e.g. 1M-token session landing in a 200k model,
///   short-window on-device contexts), retry the whole pass until it
///   fits or the per-run pass cap is hit. Each pass re-estimates tokens
///   against the freshly shrunken transcript.
///
/// Hosts inject the host-specific bits (smol resolver, summarizer,
/// persistence, progress sink) through the configuration object — there
/// is no implicit coupling to `AgentCli` or `AgentService`.
library;

import 'dart:async';
import 'dart:math' as math;
import '../cancel_token.dart';
import '../compaction/compaction.dart';
import '../compaction/token_estimation.dart';
import '../compaction/structured/engine.dart';
import '../compaction/structured/markers.dart' show localTrimMarkerPrefix;
import '../compaction/structured/judge.dart';
import '../context.dart';
import '../model.dart';
import '../session/session_tree.dart' show Session;
import 'message_cap.dart'
    show kMessageCapDefaultMargin, messageCapTriggerReached;
import '../skills/operative_pins.dart'
    show SkillOperativePins, pinnedOperativePromptBlock;
import '../skills/skills.dart' show Skill;
import '../types.dart';
import 'agent.dart' show AgentState;
import 'agent_loop.dart' show StreamFunction;
import 'tool_pairing.dart' show repairToolPairing;
