/// Per-pass outcome surfaced through [AutoCompactorHooks.onPass].
final class AutoCompactorPass {
  const AutoCompactorPass({
    required this.pass,
    required this.tokensBefore,
    required this.tokensAfter,
    required this.fallback,
    required this.ok,
    this.error,
    this.summary,
    this.hiddenRecords = 0,
    this.summarizedMessages = 0,
    this.droppedMessages = 0,
    this.marginTokens,
    this.bandTokens,
    this.hideableRemaining,
    this.judgeInputEntries,
    this.judgeInputTokens,
    this.judgeElapsedMs,
    this.judgeLatched = false,
    this.basisReadTokens,
  });

  /// 1-based pass number.
  final int pass;

  /// Estimated tokens before the pass.
  final int tokensBefore;

  /// Estimated tokens after the pass.
  final int tokensAfter;

  /// Which summarizer was used: `'smol'`, `'main'`, or `null` when the
  /// pass was skipped (no work to do).
  final String? fallback;

  /// Whether the pass succeeded.
  final bool ok;

  /// The error that failed the pass, when [ok] is `false`.
  final Object? error;

  /// The summary text the pass wrote (from the compaction record); `null`
  /// for failed / no-work / local-trim passes.
  final String? summary;

  /// Session records hidden behind the compaction boundary.
  final int hiddenRecords;

  /// Message records folded into [summary].
  final int summarizedMessages;

  /// Live-context messages dropped by the local-trim fallback (issue #673
  /// AC3): the trim frees tokens WITHOUT hiding session records or folding
  /// summaries, so a report showing only hidden/summarized cannot explain
  /// where the tokens went. 0 for every summarizer pass.
  final int droppedMessages;

  /// gh-2044 fragile-band escalation metadata (optional, never content):
  /// the settled margin that triggered the structured engine's escalation
  /// pass. Null on every pass except `structured·ckpt-escalation`.
  final int? marginTokens;

  /// gh-2044: the band the margin was measured against
  /// (`settings.reserveTokens`). Null except on escalation passes.
  final int? bandTokens;

  /// gh-2044: remaining hideable-entry count at escalation time — a
  /// diagnostic count only. Null except on escalation passes.
  final int? hideableRemaining;

  /// gh-2096 timeout diagnosis (judge-failure and probe receipts): the
  /// judged attempt's input entry count. Null on every other pass.
  final int? judgeInputEntries;

  /// gh-2096: the judged attempt's input estimated-token size. Null on
  /// every other pass.
  final int? judgeInputTokens;

  /// gh-2096: the wall-clock time the judged attempt consumed. Null on
  /// every other pass.
  final int? judgeElapsedMs;

  /// gh-2096: whether this pass was decided by the cross-run judge-health
  /// latch (a latched skip or a probe receipt).
  final bool judgeLatched;

  /// gh-2097: the upward basis jump this pass's post-append re-read
  /// revealed (the session projection held more than the in-memory view
  /// did at measurement time — a second writer). The report renders it
  /// as `basis re-read: +N` instead of a clamped `0 freed`. Null when
  /// the re-read landed on the same basis. A count only, never content.
  final int? basisReadTokens;
}

/// Hooks for a host UI to observe progress. Implementations should not
/// throw — the compactor swallows and logs around them.
abstract class AutoCompactorHooks {
  /// Called once per pass with its outcome. Used by the CLI TUI to print
  /// "auto-compacted N tokens summarized" and by the Flutter chat sheet
  /// to update the chat list.
  void onPass(AutoCompactorPass pass);

  /// Called when a pass retries on a transient error.
  void onRetry(int attempt, int maxAttempts, Duration backoff, Object error);

  /// Called once after the loop terminates, on success or exhaustion.
  void onDone(int passes, int tokens);

  /// Called when both smol and main failed in the same pass. The CLI
  /// prints a "switch models" hint here; the Flutter sheet shows a
  /// snackbar.
  void onBothRolesFailed(Object lastError);

  /// Streaming deltas (text + thinking) of the active summarization pass,
  /// so a host UI can show the summary being written instead of a silent
  /// spinner. Default no-op; high-frequency — hosts should throttle.
  void onDelta(String delta) {}

  /// Called when a summarization attempt starts, with the summarizer
  /// label (`smol=provider/model` / `main=provider/model`), the 1-based
  /// attempt number and the per-attempt budget. Hosts surface this in the
  /// busy row so a slow/dead summarizer endpoint reads as a bounded wait
  /// ("attempt 1, 300 s cap") instead of a silent hang. Default no-op.
  void onAttemptStart(String label, int attempt, Duration budget) {}
}

/// Compact helper that owns the multi-pass + retry + smol→main logic.
/// Hosts register a single [AutoCompactor.run] call after each run; the
/// helper handles everything else.
final class AutoCompactor {
  const AutoCompactor({
    required this.session,
    required this.state,
    required this.window,
    required this.settings,
    required this.summary,
    required this.mainSummary,
    required this.smolModel,
    required this.hooks,
    this.memoryExtractionHook,
    this.prompts = defaultCompactionPrompts,
    this.operativeSkills = const [],
    this.maxPasses = 8,
    this.maxAttempts = 3,
    this.baseBackoff = const Duration(seconds: 1),
    this.force = false,
    this.attemptBudget = const Duration(seconds: 300),
    this.totalBudget = const Duration(minutes: 15),
    this.runToken,
    this.messageCap,
    this.messageCapMargin = kMessageCapDefaultMargin,
  });

  /// The session to compact and to read the projected transcript from.
  final Session session;

  /// Agent state whose [AgentState.messages] is replaced with the
  /// compacted transcript on success.
  final AgentState state;

  /// The model's context window (in tokens). Used by [shouldCompact].
  final int window;

  /// Compaction thresholds (`reserveTokens`, `keepRecentTokens`,
  /// `triggerRatio`).
  final CompactionSettings settings;

  /// The summarizer used at the top of the pass chain (typically the
  /// `smol` role). May equal [mainSummary] for hosts without a separate
  /// `smol` (the helper skips the fallback in that case).
  final SummarizeFn summary;

  /// Fallback summarizer (typically the main model).
  final SummarizeFn mainSummary;

  /// The model passed to [summary] (i.e. the `smol` Model spec).
  final Model? smolModel;

  /// Progress / error sink.
  final AutoCompactorHooks hooks;

  /// Optional Phase 2 hook: forwarded to every [CompactionManager] so
  /// durable-fact extraction (CLI long-term memory, future Flutter
  /// equivalents) runs once per pass with the summarized span.
  final Future<void> Function(String summarizedText)? memoryExtractionHook;

  /// Summarization prompts forwarded to the [CompactionManager] so a
  /// host's `prompts:` yaml override reaches the same `summary` callback
  /// that `streamFunctionSummarizer` already uses.
  final CompactionPrompts prompts;

  /// gh-1409: the skills known to the session — their `operative:`
  /// directives ride every summarization prompt as the verbatim-preserve
  /// pinned block (AC3) and are protected from the sanitizer (AC4).
  /// Empty (default) → prompts byte-identical to the pre-pin pipeline
  /// (F4 compat guard).
  final List<Skill> operativeSkills;

  /// The pinned-operative payload derived from [operativeSkills] (null
  /// when the skills declare no operative lines).
  PinnedOperativePayload? get pinnedOperative =>
      pinnedOperativePayloadOf(operativeSkills);

  /// Upper bound on pass count per [run]. Picked so a 1M→200k session
  /// compacts down in 2-3 passes; deep enough for the worst case but
  /// bounded so a model that just won't summarize doesn't loop forever.
  final int maxPasses;

  /// Retry attempts per pass before falling back / failing.
  final int maxAttempts;

  /// First backoff sleep between same-pass attempts (multiplied by
  /// attempt number): 1s, 2s.
  final Duration baseBackoff;

  /// Wall-clock budget for ONE summarization attempt. A provider endpoint
  /// that accepts the request and never answers (no bytes, no error, no
  /// done) would otherwise pend `stream.result` forever and wedge the turn
  /// on the compaction spinner for as long as the user is willing to
  /// watch it — the provider-level connect/idle watchdogs cover clean
  /// hangs, but not dribbling keep-alives or a lost completion. When the
  /// budget fires the attempt fails with a [TimeoutException] (not
  /// transient — no retry spin), the pass falls to the next summarizer /
  /// the local trim, and the turn goes on. 300 s (gh-740 M1, raised from
  /// 90 s): a summarizer writes a bounded summary, and "Compacting
  /// context…" must never read as a hang (the 0.1.240 default was 10
  /// minutes per attempt — up to 20 minutes of silent spinner when both
  /// summarizers dribbled).
  final Duration attemptBudget;

  /// Wall-clock budget for the WHOLE compactor run across all passes,
  /// attempts and summarizers. Checked before each attempt: once the
  /// elapsed time is over the budget, remaining attempts are skipped and
  /// the run falls to the local trim. Bounds pathological combinations
  /// (maxPasses × retries × smol+main) that would otherwise keep the UI
  /// on the compaction spinner for tens of minutes. Defaults to
  /// `attemptBudget × maxAttempts` (15 min for the 300s gh-740 M1
  /// attempt budget) — the total must never be smaller than one attempt,
  /// or a single full timeout would exhaust it and silently collapse the
  /// retry ladder to a single attempt.
  final Duration totalBudget;

  /// When `true`, skip the [shouldCompact] gate and run the compactor
  /// unconditionally. Set by manual `/compact` (the user asked, so we
  /// honour the request even when the auto-trigger threshold isn't
  /// crossed).
  final bool force;

  /// The owning run's cancellation token (issue #1085 M1/M3), when the
  /// compaction runs inside a run (mid-run over-window relief). When it
  /// cancels — a USER abort, never the suspended watchdog — every
  /// in-flight summarization attempt is cancelled with it, so an abort
  /// kills the compaction promptly instead of waiting out the 15-30 min
  /// relief. `null` = not linked (standalone compaction).
  final CancelToken? runToken;

  /// gh-1680: the learned per-model per-request message cap. When the
  /// live message count reaches `cap − margin` the compactor fires even
  /// if the TOKEN trigger is untouched — the message-count dimension is
  /// additive, never a replacement for the token trigger (AC4/AC8). Null
  /// = no learned cap: token-only behavior, byte-identical to today.
  final int? messageCap;

  /// The margin below [messageCap] at which the pre-emptive trigger
  /// fires (see [messageCapTriggerReached]).
  final int messageCapMargin;

  /// Transient error markers worth retrying: 5xx HTTP, aborted /
  /// reset / closed sockets, and the browser fetch death (`TypeError:
  /// Failed to fetch` — an MV3 service-worker provider stream dies with
  /// exactly that string; gh-2059 arch 7). Hard refusals (rate limit,
  /// 429, content filter, auth) fail fast.
  static final _transient = RegExp(
    r'(?:5\d\d|connection\s+(?:closed|reset|aborted|refused)|'
    r'socket\s+exception|stream\s+closed|failed\s+to\s+fetch)',
    caseSensitive: false,
  );

  /// Overflow-classified failures (issue #729): the request itself cannot
  /// fit the endpoint's window — a deterministic 400 (occasionally wrapped
  /// in a 5xx). Never retried; routes straight to the next summarizer /
  /// the local trim.
  static final _overflow = RegExp(
    '(?:context length|context window|maximum context|prompt is too long|'
    'too many tokens|input length|exceed[s]? the (?:model )?(?:maximum|context)|'
    'reduce the (?:length|size))',
    caseSensitive: false,
  );

  /// The live request-size estimate in the ONE basis the ctx meter and
  /// the loop's over-window guard also enforce: transcript estimate plus
  /// the system-prompt / tool-schema overhead whenever no provider-usage
  /// anchor prices them in (post-compaction transcripts are unanchored by
  /// design — their next request still carries that overhead).
  int _requestTokens() => estimateRequestTokens(
    state.messages,
    systemPrompt: state.systemPrompt,
    tools: state.tools,
  );

  /// gh-1680: whether the live message count reached the learned cap's
  /// pre-emptive trigger (`count ≥ cap − margin`). The additive
  /// message-count dimension: fires BEFORE the provider refuses, so the
  /// request rides a compacted array instead of a doomed round-trip.
  bool _overMessageCap() => messageCapTriggerReached(
    state.messages.length,
    messageCap,
    margin: messageCapMargin,
  );

  /// Drives the multi-pass loop. Returns `true` on success (the
  /// transcript fits in [window]), `false` when the loop gave up or
  /// every summarizer failed.
  Future<bool> run() async {
    try {
      if (window <= 0) return true;
      final initial = _requestTokens();
      if (!force &&
          !shouldCompact(initial, window, settings) &&
          !_overMessageCap()) {
        return true;
      }

      final runFallback = _shouldRunFallback();
      final clock = Stopwatch()..start();

      for (var pass = 1; pass <= maxPasses; pass++) {
        final result = await _runPass(
          pass,
          runFallback: runFallback,
          clock: clock,
        );
        if (result.done) return result.success;
      }
      final tokens = _requestTokens();
      hooks.onDone(maxPasses, tokens);
      return false;
    } finally {
      // A cancelled compaction is NEVER a mere failed pass (issue #1085
      // round-4): both engines fold a cancelled summarizer into
      // `ok: false`, which callers read as "nothing changed" — the
      // over-window funnel then RELAUNCHES the compaction the user just
      // stopped. Surface the cancel as an exception so every host's
      // abort handling sees it; a success that races a late cancel is
      // equally dead (the next request rides a cancelled run token).
      runToken?.throwIfCancelled();
    }
  }

  /// gh-1743: host-callable emergency valve for a timed-out compaction —
  /// applies the same mechanical local trim [_localTrimFallback] the
  /// classic pass ladder ends on (keep the most recent
  /// [CompactionSettings.keepRecentTokens], repair tool pairing, prefix
  /// the `[context trimmed locally]` marker), fires the `local-trim` pass
  /// receipt and closes the [AutoCompactorHooks.onDone] bracket exactly
  /// like the `_runPass` trim branch, and reports whether the live
  /// context was actually bounded. `false` means nothing was droppable —
  /// the caller keeps its failure verdict.
  ///
  /// Deliberately NOT gated on `_runPass`'s under-trigger check
  /// (`!shouldCompact && !_overMessageCap`): the gh-1425 clamp lands the
  /// trim under the TOKEN trigger by construction, so the only dimension
  /// that can stay over is the gh-1680 message cap (many tiny kept
  /// messages). This boolean answers "does the session live" for the
  /// over-window funnel — a `false` here aborts the live task, gh-1743's
  /// whole bug — and a still-over-cap context self-heals at the next
  /// turn's pre-flight compaction, which fires on the message-cap
  /// dimension and runs the healthy LM path. A cancelled [runToken]
  /// throws before anything is trimmed or reported (issue #1085 cancel
  /// parity with [run]).
  bool applyLocalTrimFallback({int pass = 1}) {
    // Cancel parity (issue #1085): a cancelled compaction is NEVER a
    // mere failed pass. If the owning run's token cancelled around the
    // moment the budget fired, surface the abort instead of trimming —
    // and reporting success on — a run the user stopped.
    runToken?.throwIfCancelled();
    final tokensBefore = _requestTokens();
    final trimmed = _localTrimFallback();
    if (trimmed == null) return false;
    state.messages = trimmed.messages;
    final tokensAfter = _requestTokens();
    hooks.onPass(
      AutoCompactorPass(
        pass: pass,
        tokensBefore: tokensBefore,
        tokensAfter: tokensAfter,
        fallback: 'local-trim',
        ok: true,
        droppedMessages: trimmed.dropped,
      ),
    );
    hooks.onDone(pass, tokensAfter);
    return true;
  }

  /// Whether the smol summarizer is distinct from the main one and should be
  /// tried before falling back to main.
  bool _shouldRunFallback() {
    final smol = smolModel;
    if (smol == null) return false;
    final mainModel = state.model;
    return smol.provider != mainModel.provider || smol.id != mainModel.id;
  }

  /// Runs one compaction pass. Returns `done: true` when the loop should
  /// terminate (success or hard failure), `done: false` when another pass is
  /// needed.
  Future<({bool done, bool success})> _runPass(
    int pass, {
    required bool runFallback,
    required Stopwatch clock,
  }) async {
    final tokensBefore = _requestTokens();
    final mainModel = state.model;
    final smolModel = this.smolModel;

    final attempt = await _pickAttempt(
      pass,
      runFallback: runFallback,
      mainLabel: _modelLabel(mainModel),
      smolLabel: smolModel == null ? 'default' : _modelLabel(smolModel),
      clock: clock,
    );

    if (!attempt.ok) {
      // Both summarizers down: as a last resort, mechanically bound the
      // live context (see [_localTrimFallback]) so the agent can keep
      // working instead of being stuck over-window until the endpoint
      // recovers.
      final trimmed = _localTrimFallback();
      if (trimmed != null) {
        state.messages = trimmed.messages;
        final tokensAfter = _requestTokens();
        hooks.onPass(
          AutoCompactorPass(
            pass: pass,
            tokensBefore: tokensBefore,
            tokensAfter: tokensAfter,
            fallback: 'local-trim',
            ok: true,
            droppedMessages: trimmed.dropped,
          ),
        );
        hooks.onDone(pass, tokensAfter);
        return (
          done: true,
          success:
              !shouldCompact(tokensAfter, window, settings) &&
              !_overMessageCap(),
        );
      }
      hooks.onBothRolesFailed(attempt.error!);
      hooks.onPass(
        AutoCompactorPass(
          pass: pass,
          tokensBefore: tokensBefore,
          tokensAfter: tokensBefore,
          fallback: null,
          ok: false,
          error: attempt.error,
        ),
      );
      hooks.onDone(pass, _requestTokens());
      return (done: true, success: false);
    }

    // A no-op pass (the branch is already compacted at the leaf): stop
    // instead of spinning identical passes to maxPasses.
    if (attempt.noWork) {
      hooks.onPass(
        AutoCompactorPass(
          pass: pass,
          tokensBefore: tokensBefore,
          tokensAfter: tokensBefore,
          fallback: attempt.fallback,
          ok: true,
        ),
      );
      hooks.onDone(pass, tokensBefore);
      return (done: true, success: true);
    }

    // Pass succeeded — re-stamp the in-memory transcript with the
    // session's projected context, then re-estimate. The kept assistant
    // messages carry generation-time usage from BEFORE the compaction —
    // anchoring the estimator at it would keep reporting the
    // pre-compaction size and retrigger the loop forever. Clear it; the
    // next turn's usage report re-anchors the estimate.
    state.messages = [
      for (final message in await session.buildContextMessages())
        if (message is AssistantMessage)
          message.copyWith(usage: Usage.zero)
        else
          message,
    ];
    final tokensAfter = _requestTokens();
    hooks.onPass(
      AutoCompactorPass(
        pass: pass,
        tokensBefore: tokensBefore,
        tokensAfter: tokensAfter,
        fallback: attempt.fallback,
        ok: true,
        summary: attempt.summary,
        hiddenRecords: attempt.hiddenRecords,
        summarizedMessages: attempt.summarizedMessages,
      ),
    );
    if (!shouldCompact(tokensAfter, window, settings) && !_overMessageCap()) {
      hooks.onDone(pass, tokensAfter);
      return (done: true, success: true);
    }
    return (done: false, success: false);
  }

  /// Emergency valve when both summarizers are down and the transcript is
  /// over the window: mechanically keep the most recent
  /// [CompactionSettings.keepRecentTokens] (estimated) messages, prefixing
  /// a user-role marker so the model (and providers, which reject
  /// toolResult-first transcripts) see what happened. In-memory only — the
  /// session file keeps every record; the next restart replays the full
  /// transcript and the pre-flight compaction retries the LLM path with a
  /// healthy endpoint. Returns null when there is nothing droppable (the
  ({List<Message> messages, int dropped})? _localTrimFallback() =>
      localTrimValve(
        messages: state.messages,
        reason: 'the summarizer endpoint was unavailable',
        window: window,
        settings: settings,
        overheadTokens: estimateRequestTokens(
          const [],
          systemPrompt: state.systemPrompt,
          tools: state.tools,
        ),
      );

  /// Picks the summarizer for this pass: smol first, main as fallback when
  /// [runFallback] is true. Returns the outcome, the fallback label used and
  /// the winning attempt's record data (summary + hidden/summarized counts)
  /// for the pass report.
  Future<_PickOutcome> _pickAttempt(
    int pass, {
    required bool runFallback,
    required String mainLabel,
    required String smolLabel,
    required Stopwatch clock,
  }) async {
    if (runFallback) {
      final smolOk = await _attempt(
        'smol=$smolLabel',
        summarize: summary,
        pass: pass,
        clock: clock,
        // E1 (#729): chunk sizing uses the SUMMARIZER's window, never the
        // main model's — a smaller smol role gets smaller chunks.
        summarizerWindow: smolModel?.contextWindow,
      );
      if (smolOk.ok) {
        return _PickOutcome(
          ok: true,
          error: null,
          noWork: smolOk.noWork,
          fallback: 'smol=$smolLabel',
          summary: smolOk.summary,
          hiddenRecords: smolOk.hiddenRecords,
          summarizedMessages: smolOk.summarizedMessages,
        );
      }
      final mainOk = await _attempt(
        'main=$mainLabel',
        summarize: mainSummary,
        pass: pass,
        clock: clock,
        summarizerWindow: window,
      );
      if (mainOk.ok) {
        return _PickOutcome(
          ok: true,
          error: null,
          noWork: mainOk.noWork,
          fallback: 'main=$mainLabel',
          summary: mainOk.summary,
          hiddenRecords: mainOk.hiddenRecords,
          summarizedMessages: mainOk.summarizedMessages,
        );
      }
      return _PickOutcome(
        ok: false,
        error: mainOk.error ?? smolOk.error,
        noWork: false,
        fallback: null,
        summary: null,
        hiddenRecords: 0,
        summarizedMessages: 0,
      );
    }

    // No smol role, or smol == main: single attempt on the main stream.
    final mainOk = await _attempt(
      'main=$mainLabel',
      summarize: mainSummary,
      pass: pass,
      clock: clock,
      summarizerWindow: window,
    );
    if (mainOk.ok) {
      return _PickOutcome(
        ok: true,
        error: null,
        noWork: mainOk.noWork,
        fallback: 'main=$mainLabel',
        summary: mainOk.summary,
        hiddenRecords: mainOk.hiddenRecords,
        summarizedMessages: mainOk.summarizedMessages,
      );
    }
    return _PickOutcome(
      ok: false,
      error: mainOk.error,
      noWork: false,
      fallback: null,
      summary: null,
      hiddenRecords: 0,
      summarizedMessages: 0,
    );
  }

  /// Runs one pass with up to [maxAttempts] retries on transient errors.
  /// Returns the outcome plus, on success, the compaction record's summary
  /// and the hidden/summarized counts (computed from the branch up to
  /// `firstKeptEntryId`) for the pass report. `noWork` means the branch had
  /// nothing left to compact (already compacted at the leaf) — the caller
  /// stops the pass loop instead of spinning identical no-op passes to
  /// [maxPasses].
  Future<_AttemptOutcome> _attempt(
    String label, {
    required SummarizeFn summarize,
    required int pass,
    required Stopwatch clock,
    required int? summarizerWindow,
  }) async {
    if (smolModel == null) {
      // Resolved via the main chain only — skip the label-based attempt.
    }
    for (var attempt = 1; attempt <= maxAttempts; attempt++) {
      if (clock.elapsed >= totalBudget) {
        return _AttemptOutcome(
          ok: false,
          error: TimeoutException(
            'compaction total budget (${totalBudget.inSeconds}s) exhausted '
            'before the $label attempt',
            totalBudget,
          ),
          noWork: false,
          summary: null,
          hiddenRecords: 0,
          summarizedMessages: 0,
        );
      }
      hooks.onAttemptStart(label, attempt, attemptBudget);
      try {
        final manager = CompactionManager(
          summarize: summarize,
          settings: settings,
          prompts: prompts,
          memoryExtractionHook: memoryExtractionHook,
          // Issue #729: bound this summarizer's outbound payloads to its
          // own window — chunked summarization inside the pass.
          summarizerWindow: summarizerWindow,
          // gh-1409: pinned skill directives ride the verbatim-preserve
          // block; the sanitizer protects them (AC3/AC4).
          pinnedOperative: pinnedOperative,
        );
        // Issue #515: the budget kill must abort the underlying request,
        // not abandon it — an endpoint that accepts and never answers
        // would otherwise keep the connection (and the retry pass) alive
        // past the timeout.
        final attemptToken = CancelTokenSource();
        // Issue #1085: a linked run token (mid-run relief) forwards its
        // cancellation to the in-flight attempt — the user abort reaches
        // the summarizer within a microtask hop instead of waiting out
        // the whole relief.
        final runToken = this.runToken;
        if (runToken != null) {
          unawaited(
            runToken.onCancel.then(
              (_) => attemptToken.cancel(runToken.cancelReason),
            ),
          );
        }
        final compacting = manager.compactSession(
          session,
          cancelToken: attemptToken.token,
        );
        final record = await compacting.timeout(
          attemptBudget,
          onTimeout: () {
            final timeout = TimeoutException(
              'compaction attempt exceeded the '
              '${attemptBudget.inSeconds}s budget',
              attemptBudget,
            );
            attemptToken.cancel(timeout);
            compacting.ignore();
            throw timeout;
          },
        );
        if (record == null) {
          return _AttemptOutcome(
            ok: true,
            error: null,
            noWork: true,
            summary: null,
            hiddenRecords: 0,
            summarizedMessages: 0,
          );
        }
        final (hidden, summarized) = await _compactionCounts(record);
        return _AttemptOutcome(
          ok: true,
          error: null,
          noWork: false,
          summary: record.summary,
          hiddenRecords: hidden,
          summarizedMessages: summarized,
        );
      } catch (error) {
        final errorText = error.toString();
        final isTransient = _transient.hasMatch(errorText);
        // Issue #729 AC2: an overflow-classified failure is DETERMINISTIC —
        // the payload cannot fit this endpoint no matter how often it is
        // retried. Route immediately to the next summarizer / the local
        // trim with ZERO backoff retries, even when the provider wraps the
        // 400 in a transient-shaped message.
        final isOverflow = _overflow.hasMatch(errorText);
        if (isOverflow || attempt >= maxAttempts || !isTransient) {
          return _AttemptOutcome(
            ok: false,
            error: error,
            noWork: false,
            summary: null,
            hiddenRecords: 0,
            summarizedMessages: 0,
          );
        }
        final backoff = baseBackoff * attempt;
        hooks.onRetry(attempt, maxAttempts, backoff, error);
        await Future<void>.delayed(backoff);
      }
    }
    return _AttemptOutcome(
      ok: false,
      error: StateError('unreachable: compact attempt loop'),
      noWork: false,
      summary: null,
      hiddenRecords: 0,
      summarizedMessages: 0,
    );
  }

  /// Counts the records hidden behind [record]'s compaction boundary and
  /// the message records folded into its summary — one branch walk, ids
  /// only (never positions).
  Future<(int, int)> _compactionCounts(CompactionRecord record) async {
    final path = await session.getBranch();
    final keptIndex = path.indexWhere((e) => e.id == record.firstKeptEntryId);
    final hidden = keptIndex <= 0 ? 0 : keptIndex;
    var summarized = 0;
    for (final entry in path.take(hidden)) {
      if (entry is MessageRecord) summarized++;
    }
    return (hidden, summarized);
  }
}

String _modelLabel(Model m) => '${m.provider}/${m.id}';

/// One summarizer attempt's outcome: the ok/error verdict plus, on
/// success, the compaction record's summary and hidden/summarized
/// counts. A class, not a record — 6 fields exceeded the record_size
/// cap (issue #1997).
final class _AttemptOutcome {
  const _AttemptOutcome({
    required this.ok,
    required this.error,
    required this.noWork,
    required this.summary,
    required this.hiddenRecords,
    required this.summarizedMessages,
  });

  final bool ok;
  final Object? error;
  final bool noWork;
  final String? summary;
  final int hiddenRecords;
  final int summarizedMessages;
}

/// [_AttemptOutcome] plus the fallback label that won (smol/main), for
/// the pass report. A class for the same record_size reason (issue
/// #1997).
final class _PickOutcome {
  const _PickOutcome({
    required this.ok,
    required this.error,
    required this.noWork,
    required this.fallback,
    required this.summary,
    required this.hiddenRecords,
    required this.summarizedMessages,
  });

  final bool ok;
  final Object? error;
  final bool noWork;
  final String? fallback;
  final String? summary;
  final int hiddenRecords;
  final int summarizedMessages;
}

/// The mechanical over-window valve, host-callable (the resume boot cap
/// applies it INSTANTLY when a resumed transcript cannot fit the window:
/// an LM compaction pass there takes minutes on slow providers and blocks
/// the whole boot — the goal_builder incident). Semantics are exactly
/// [_localTrimFallback]'s; see there for the contract.
({List<Message> messages, int dropped})? localTrimValve({
  required List<Message> messages,
  required String reason,
  required int window,
  required CompactionSettings settings,
  required int overheadTokens,
}) {
  if (messages.isEmpty) return null;
  // gh-1425: the valve must land UNDER the compaction trigger, not
  // merely at keepRecentTokens — a keepRecent-sized tail plus the
  // system-prompt/tool-schema overhead can sit above
  // `window - reserveTokens`, so the next turn's auto-compact re-fires
  // immediately and, with both summarizers still down, the session is
  // stuck again (the exact marathon-resume cliff this valve exists
  // for). Clamp the kept budget to the trigger minus the per-request
  // overhead; keepRecentTokens still wins when it is smaller. Three
  // edge guards (gh-1425 review + flutter_app IT-2):
  // - reserve the [context trimmed] marker's own tokens (~64) so the
  //   kept region plus marker still lands under the trigger;
  // - floor the clamp at the newest message's tokens — a degenerate
  //   overhead (≥ the trigger) must still trim SOMETHING, never return
  //   an empty window (the projectedBranchBudgetCut rule);
  // - but only up to keepRecentTokens: a newest message LARGER than
  //   keepRecentTokens must keep the budget AT keepRecentTokens so the
  //   walk still finds "nothing droppable" and returns null — that
  //   null is the failure the summarizer-ladder exhaustion surfaces
  //   (gh-1077 AC2: the app's fix-location notice fires on it, and the
  //   transcript stays intact instead of silently dropping the user's
  //   newest turn).
  final overhead = overheadTokens;
  final budget = math.min(
    settings.keepRecentTokens,
    math.max(
      math.max(0, window - settings.reserveTokens - overhead - 64),
      estimateTokens(messages.last), // never an empty window
    ),
  );
  var cut = 0; // first kept index
  var accumulated = 0;
  for (var i = messages.length - 1; i >= 0; i--) {
    accumulated += estimateTokens(messages[i]);
    if (accumulated > budget) {
      cut = i + 1;
      break;
    }
  }
  if (cut <= 0) return null;
  final kept = messages.sublist(cut);
  if (kept.isEmpty) return null;
  // Pairing integrity (issue #85): a token-boundary cut can land between
  // an assistant tool call and its result, leaving an orphaned result at
  // ANY position of the kept region — the production wedge survived the
  // old leading-only skip as the second block of a merged wire message
  // (`messages.0.content.1`). The request-boundary repairer is the single
  // generalization: drops orphan results (with a visible note),
  // synthesizes missing results, hoists displaced ones. In-memory only —
  // the session file keeps every record.
  final rebuilt = repairToolPairing([
    UserMessage.text(
      '$localTrimMarkerPrefix $reason, '
      '$cut older message(s) were dropped from the live context at '
      '${DateTime.now().toUtc().toIso8601String()} — the full history '
      'stays in the session file]',
    ),
    // Zero the kept generations' usage anchors — a stale generation-time
    // anchor would keep the estimate over the window and retrigger the
    // compactor on the next turn (same rule as the success pass).
    for (final message in kept)
      if (message is AssistantMessage)
        message.copyWith(usage: Usage.zero)
      else
        message,
  ]);
  return (messages: rebuilt.messages, dropped: cut);
}

/// Source for the [AutoCompactor] smol/main summarizers. Hosts plug in
/// their own resolver:
/// - the CLI uses `config.modelRolesResolver?.resolveRole(smolModelRole)`
/// - the Flutter app uses `_taskModelsStore?.overrideFor(TaskRole.smol)`
///
/// Either source may be `null` when no smol is configured; in that case
/// [AutoCompactor.fromSources] falls back to [mainStream] for both
/// summarizers and skips the smol→main fallback (one attempt only —
/// retrying the same call wouldn't help).
class AutoCompactorSources {
  const AutoCompactorSources({
    required this.smolStream,
    required this.smolModel,
    required this.mainStream,
    required this.mainModel,
  });

  /// When `null`, the AutoCompactor uses [mainStream] + [mainModel] for
  /// both summarizers and skips the fallback (single attempt).
  final StreamFunction? smolStream;

  /// The Model spec the smol summarizer should call. `null` together
  /// with [smolStream] → no real smol.
  final Model? smolModel;

  /// Fallback summarizer stream (typically the main chat stream).
  final StreamFunction mainStream;

  /// Fallback summarizer model (typically the agent's main model).
  final Model mainModel;
}

/// Builds the gh-1409 summarization payload for [skills]: the rendered
/// verbatim-preserve block plus the raw pin lines for the sanitizer's
/// exemption. `null` when the skills declare no operative lines (the
/// ONE derivation shared by [AutoCompactor] and [AutoCompactorFactory]).
PinnedOperativePayload? pinnedOperativePayloadOf(List<Skill> skills) {
  if (skills.isEmpty) return null;
  final registry = SkillOperativePins.build(skills);
  if (registry.isEmpty) return null;
  final block = pinnedOperativePromptBlock(registry);
  if (block == null) return null;
  return PinnedOperativePayload(
    block: block,
    lines: {for (final pin in registry.pins) pin.line},
  );
}

/// Compact helper that owns the multi-pass + retry + smol→main logic for
/// hosts that build their compactor through the factory: the factory
/// wires the smol/main summarizers with the configured
/// [CompactionPrompts] and optional memory hook, then runs the loop.
///
/// When [force] is `true` the compactor skips [shouldCompact] — used by
/// manual `/compact` so the user can force a compaction regardless of
/// the auto-trigger threshold.
class AutoCompactorFactory {
  const AutoCompactorFactory({
    required this.session,
    required this.state,
    required this.window,
    required this.settings,
    required this.sources,
    required this.hooks,
    this.prompts = defaultCompactionPrompts,
    this.memoryExtractionHook,
    this.maxPasses = 8,
    this.maxAttempts = 3,
    this.baseBackoff = const Duration(seconds: 1),
    this.force = false,
    this.attemptBudget = const Duration(seconds: 300),
    this.totalBudget = const Duration(minutes: 15),
    this.engine = CompactionEngine.structured,
    this.runToken,
    this.operativeSkills = const [],
    this.messageCap,
    this.messageCapMargin = kMessageCapDefaultMargin,
  });

  final Session session;
  final AgentState state;
  final int window;
  final CompactionSettings settings;
  final AutoCompactorSources sources;
  final AutoCompactorHooks hooks;
  final CompactionPrompts prompts;
  final Future<void> Function(String)? memoryExtractionHook;
  final int maxPasses;
  final int maxAttempts;
  final Duration baseBackoff;
  final bool force;

  /// Which engine compactions use (issue #148 D8):
  /// [CompactionEngine.structured] (the default since issue #287) or
  /// [CompactionEngine.classic] (the legacy 1.0 rollback — lossy prefix
  /// summary; the structured engine also falls back to it when it cannot
  /// get the context under the window).
  final CompactionEngine engine;

  /// The owning run's cancellation token (issue #1085), forwarded to the
  /// built [AutoCompactor] and linked to the structured engine's budget
  /// token: a user abort during a mid-run relief cancels the in-flight
  /// compaction on BOTH engines. `null` = standalone compaction.
  final CancelToken? runToken;

  /// gh-1409: the session's skills, forwarded to the built
  /// [AutoCompactor] — their `operative:` lines ride every summarization
  /// prompt as the verbatim-preserve pinned block.
  final List<Skill> operativeSkills;

  /// gh-1680: the learned per-model per-request message cap, forwarded to
  /// the built [AutoCompactor]: `count ≥ cap − margin` fires the
  /// pre-emptive trigger even when the token trigger is untouched (AC4).
  /// Null = token-only behavior, byte-identical to today (AC8).
  final int? messageCap;

  /// The margin below [messageCap] at which the pre-emptive trigger
  /// fires (see [messageCapTriggerReached]).
  final int messageCapMargin;

  /// The pinned-operative payload derived from [operativeSkills] (null
  /// when the skills declare no operative lines).
  PinnedOperativePayload? get pinnedOperative =>
      pinnedOperativePayloadOf(operativeSkills);

  /// Per-attempt wall-clock budget, forwarded to the built [AutoCompactor].
  final Duration attemptBudget;

  /// Whole-run wall-clock budget, forwarded to the built [AutoCompactor].
  /// Defaults to 15 min (`attemptBudget × maxAttempts`); see the
  /// [AutoCompactor.totalBudget] doc for why it must stay in step with
  /// the per-attempt budget.
  final Duration totalBudget;

  /// The live request-size estimate on the same basis the structured
  /// engine enforces (transcript + system-prompt/tool-schema overhead).
  int _requestTokens() => estimateRequestTokens(
    state.messages,
    systemPrompt: state.systemPrompt,
    tools: state.tools,
  );

  /// Builds the [AutoCompactor] and runs it. Hosts that want to
  /// inspect the compactor before starting (e.g. for logging) can use
  /// [build] instead.
  Future<bool> run() async {
    if (engine == CompactionEngine.structured) {
      // gh-1680: a reached message-cap trigger forces the pass exactly
      // like `force` — the structured engine's internal gate is
      // token-only, so the additive message-count dimension must bypass
      // it here (AC4). Computed up front so the zero-pass fall-through
      // below covers the cap channel identically.
      final capTriggered = messageCapTriggerReached(
        state.messages.length,
        messageCap,
        margin: messageCapMargin,
      );
      final adapter = _StructuredHooksAdapter(hooks);
      final outcome = await _runStructured(
        adapter: adapter,
        capTriggered: capTriggered,
      );
      // gh-1742 invariant 1: a FORCED run (observed usage over the line)
      // that did zero passes is not relief — the structured engine's
      // pass loops gate on its own transcript estimate, so an
      // observation the estimate cannot see would come back `ok` with
      // nothing done and the child would ride an over-window context
      // into the next request. Fall through to the classic engine,
      // whose forced semantics run the summarizer regardless of its
      // own estimate. An unforced no-op stays the success short-circuit.
      if (outcome.ok && (adapter.passCount > 0 || !(force || capTriggered))) {
        // Close the hooks bracket the classic [AutoCompactor.run] closes
        // on every terminal path: hosts key off [AutoCompactorHooks.onDone]
        // (the CLI's HEP `compaction_end` frame, the Flutter chat sheet),
        // so a structured run that skips it leaves them open forever.
        hooks.onDone(adapter.passCount, _requestTokens());
        return true;
      }
      if (outcome.timedOut) {
        // Budget kill (issue #515): the summarizer/judge wedged past the
        // watchdog budget and the underlying call was aborted. gh-1743:
        // do NOT abort the live session — re-running the classic engine
        // here would only re-wedge the same endpoint, but the mechanical
        // local trim needs no endpoint at all: bound the live context
        // (keepRecentTokens, pairing-repaired, `[context trimmed locally]`
        // marker) so the run proceeds. The failure verdict is kept only
        // when there is nothing left to trim.
        final trimmed = build().applyLocalTrimFallback(
          pass: adapter.passCount + 1,
        );
        if (trimmed) return true;
        hooks.onBothRolesFailed(outcome.error!);
        // This is a terminal path like any other: report the failed pass
        // and close the host bracket (mirrors the classic engine's
        // exhaustion branch). Skipping it left the CLI's HEP
        // `compaction_start` bracket open and `_runTokensBefore` stale —
        // the next compaction's freed-delta frame computed against the
        // failed run's before-count.
        hooks.onPass(
          AutoCompactorPass(
            pass: adapter.passCount + 1,
            tokensBefore: _requestTokens(),
            tokensAfter: _requestTokens(),
            fallback: null,
            ok: false,
            error: outcome.error,
          ),
        );
        hooks.onDone(adapter.passCount + 1, _requestTokens());
        return false;
      }
      // Fall through: the classic prefix compactor is the residual
      // fallback (issue #148 flowchart S7/D4) — its summary then renders
      // under structured projection as an opaque legacy-ckpt segment.
      // Its own run() closes the bracket.
    }
    return build().run();
  }

  Future<({bool ok, bool timedOut, Object? error})> _runStructured({
    _StructuredHooksAdapter? adapter,
    bool capTriggered = false,
  }) async {
    final smolStream = sources.smolStream ?? sources.mainStream;
    final smolModel = sources.smolModel ?? sources.mainModel;
    // One budget token for the whole structured run: both the judge and
    // the summarizer adapters receive it, and the budget expiries below
    // cancel it so the wedged call dies at the provider layer (#515).
    final budgetSource = CancelTokenSource();
    // Issue #1085: forward a linked run token's cancellation into the
    // budget token — a user abort mid-relief kills the structured run's
    // in-flight judge/summarizer calls promptly.
    final runToken = this.runToken;
    if (runToken != null) {
      unawaited(
        runToken.onCancel.then(
          (_) => budgetSource.cancel(runToken.cancelReason),
        ),
      );
    }
    final compactor = StructuredCompactor(
      session: session,
      state: state,
      window: window,
      settings: settings,
      // gh-2044 rework (review thread 3): the factory's run token is the
      // AUTHORITATIVE user-abort signal for the engine's `_runCancelled`.
      // Before this wiring the engine inferred "user abort" from a
      // cancel-REASON type heuristic on the budget token
      // (`cancelReason is! TimeoutException`), so a watchdog-shaped
      // cancel (any TimeoutException reason — the link forwards
      // `runToken.cancelReason` verbatim) was silently misclassified as
      // a budget kill: the escalation proceeded, its LM call died, and
      // the abort dissolved into a "summarizer returned no text" failed
      // receipt while the run reported success (#1085). With the token
      // wired, the first `_runCancelled` clause decides and the
      // reason-type heuristic degrades to a harmless fallback for
      // callers that only pass budgetSource.
      cancelToken: runToken,
      // gh-2096: the judge adapter receives NO baked-in run-wide token —
      // the engine hands every judge call a PER-CALL child token (a
      // budget timeout aborts only the in-flight call; the retry and the
      // later LM stages keep the run-wide token live) and forwards this
      // run's cancels into it. Wiring the run-wide token here was the
      // incident's born-cancelled retry: the first judge timeout killed
      // the shared token and every later call failed in ~75 ms.
      judge: streamFunctionHideJudge(
        smolStream,
        smolModel,
        system: prompts.hideJudgeSystem,
        onDelta: hooks.onDelta,
      ),
      summarize: streamFunctionSummarizer(smolStream, smolModel),
      // Issue #729: the checkpoint payloads are bounded by the
      // SUMMARIZER's window (the smol role when configured), not the main
      // model's.
      summarizerWindow: (sources.smolModel ?? sources.mainModel).contextWindow,
      checkpointPrompt: pinnedOperative == null
          ? prompts.structuredCheckpoint
          // gh-1409 E7: the structured checkpoint carries the
          // verbatim-preserve duty too.
          : '${prompts.structuredCheckpoint}\n\n${prompts.pinnedOperative}',
      pinnedOperativeBlock: pinnedOperative?.block,
      pinnedLines: pinnedOperative?.lines ?? const {},
      hooks: adapter ?? _StructuredHooksAdapter(hooks),
      budgetSource: budgetSource,
      // #541: the knob actually bounds the judge — the factory's
      // attemptBudget reaches the engine's per-call budget, and the
      // named failure line carries the smol judge's identity.
      attemptBudget: attemptBudget,
      judgeTarget:
          'role=smol, model=${smolModel.id} @ '
          '${Uri.parse(smolModel.baseUrl).host}',
    );
    // gh-1680: the cap trigger is computed by [run] and handed in so a
    // forced-but-zero-pass structured outcome can fall through to the
    // classic engine there (gh-1742 invariant 1).
    final running = compactor.run(force: force || capTriggered);
    try {
      final ok = await running.timeout(
        totalBudget,
        onTimeout: () {
          final timeout = TimeoutException(
            'structured compaction exceeded the '
            '${totalBudget.inSeconds}s total budget (issue #515)',
            totalBudget,
          );
          // Kill the wedged call at the provider layer, then surface.
          compactor.cancelBudget(timeout);
          throw timeout;
        },
      );
      return (ok: ok, timedOut: false, error: null);
    } on TimeoutException catch (error) {
      // The engine run may settle later (the abort propagates
      // asynchronously); drop that late settle — the named failure here
      // is the authoritative outcome.
      running.ignore();
      return (ok: false, timedOut: true, error: error);
    }
  }

  /// Builds the [AutoCompactor] from the factory's configuration without

[Showing lines 1-1271 of 1374 (50.0KB limit). Use offset=1272 to continue.]

  /// starting it. Useful for tests or for hosts that want to wrap the
  /// loop in extra logging.
  AutoCompactor build() {
    final smolStream = sources.smolStream ?? sources.mainStream;
    final smolModel = sources.smolModel ?? sources.mainModel;
    // gh-1433 E4: the summarizer adapters forward their streaming deltas
    // (text + thinking) to the host hooks — on the classic engine the
    // summarizer IS the whole compaction, and its stream used to vanish
    // behind a busy row that does not exist in a captured log.
    final smolSummarizer = streamFunctionSummarizer(
      smolStream,
      smolModel,
      prompts: prompts,
      onDelta: hooks.onDelta,
    );
    final mainSummarizer = streamFunctionSummarizer(
      sources.mainStream,
      sources.mainModel,
      prompts: prompts,
      onDelta: hooks.onDelta,
    );
    return AutoCompactor(
      session: session,
      state: state,
      window: window,
      settings: settings,
      summary: smolSummarizer,
      mainSummary: mainSummarizer,
      smolModel: sources.smolModel,
      hooks: hooks,
      memoryExtractionHook: memoryExtractionHook,
      prompts: prompts,
      maxPasses: maxPasses,
      maxAttempts: maxAttempts,
      baseBackoff: baseBackoff,
      force: force,
      attemptBudget: attemptBudget,
      totalBudget: totalBudget,
      runToken: runToken,
      operativeSkills: operativeSkills,
      messageCap: messageCap,
      messageCapMargin: messageCapMargin,
    );
  }
}

/// Adapts [StructuredCompactorHooks] onto [AutoCompactorHooks] so host UIs
/// (CLI busy row, Flutter chat sheet) observe structured passes unchanged.
final class _StructuredHooksAdapter implements StructuredCompactorHooks {
  _StructuredHooksAdapter(this._hooks);

  final AutoCompactorHooks _hooks;

  /// Completed structured passes — the factory reports the count through
  /// [AutoCompactorHooks.onDone] when the run succeeds.
  int passCount = 0;

  @override
  void onDelta(String delta) => _hooks.onDelta(delta);

  @override
  void onPass(StructuredCompactionPass pass) {
    passCount++;
    _hooks.onPass(
      AutoCompactorPass(
        pass: pass.pass,
        tokensBefore: pass.tokensBefore,
        tokensAfter: pass.tokensAfter,
        // Name the engine + pass kind: a host watching the report can
        // tell a structured fold from a classic summary (issue #438),
        // and the deterministic judge-less hide from a judged one
        // (issue #541).
        fallback: switch (pass.kind) {
          'checkpoint' => 'structured·ckpt',
          'checkpoint-escalation' => 'structured·ckpt-escalation',
          'hide-fallback' => 'structured·hide-fallback',
          'hide-lru' => 'structured·hide-lru',
          _ => 'structured·hide',
        },
        ok: pass.ok,
        error: pass.error,
        hiddenRecords: pass.hiddenCount,
        summarizedMessages: pass.summarizedCount,
        summary: pass.summary,
        // gh-2044: the escalation's numeric reason rides to the host
        // reporting (margin/band/outcome) — counts only, never content.
        marginTokens: pass.marginTokens,
        bandTokens: pass.bandTokens,
        hideableRemaining: pass.hideableRemaining,
        // gh-2096: the judge attempt shape and the latch flag ride to the
        // host reporting the same way — counts and a flag, never content.
        judgeInputEntries: pass.judgeInputEntries,
        judgeInputTokens: pass.judgeInputTokens,
        judgeElapsedMs: pass.judgeElapsedMs,
        judgeLatched: pass.judgeLatched,
        // gh-2097: the upward re-read basis jump rides to the host
        // reporting — a count only, never content.
        basisReadTokens: pass.basisReadTokens,
      ),
    );
  }
}

/// The context ledger for the structured compaction engine (issue #148).
///
/// The judge model never sees raw history — it sees one line per visible
/// projecting record:
///
/// ```
/// [2] user·exempt ~68tok · fix the login crash
/// [3] assistant-TOOLCALL(read) ~40tok
/// [4] toolResult(read) ~4.0k · x.dart contents…
/// [5] ckpt 2-4 ~38k → covers:3,4 · summary text…
/// ```
///
/// Real user turns are tagged `·exempt` and can never be hidden (F8/F9):
/// user steering must survive every pass. Tool-call carriers carry their
/// tool names so the judge can reason about pairs (F3), and every entry
/// knows the pair group it belongs to — groups hide atomically (D6).
library;

import '../token_estimation.dart' show estimateTokens;
import '../../context.dart';
import '../../types.dart';
import '../../session/session_record.dart';
import 'projection.dart';
import '../compaction.dart';

/// One visible line of the ledger.
final class LedgerEntry {
  const LedgerEntry._({
    required this.seq,
    required this.recordId,
    required this.record,
    required this.kind,
    required this.tokens,
    required this.preview,
    required this.toolNames,
  });

  /// The record's numeric alias (JSONL line number).
  final int seq;

  /// The record's stable id.
  final String recordId;

  /// The underlying record.
  final SessionRecord record;

  /// The kind label (`user`, `notice`, `assistant-TEXT`,
  /// `assistant-TOOLCALL(read,bash)`, `toolResult(read)`, `ckpt`,
  /// `legacy-ckpt`, `branch-summary`).
  final String kind;

  /// Estimated tokens of the record's projection.
  final int tokens;

  /// Flattened first line of content (~110 chars).
  final String preview;

  /// Comma-joined tool names for call/result entries.
  final String toolNames;

  /// Real user turns can never be hidden.
  bool get exempt => kind == 'user';
}

/// The judge-facing index of visible records.
final class ContextLedger {
  ContextLedger._(this.entries, this._groupByRecordId)
    : _entryBySeq = {for (final entry in entries) entry.seq: entry};

  /// Visible projecting records, oldest first.
  final List<LedgerEntry> entries;

  final Map<String, Set<String>> _groupByRecordId;

  final Map<int, LedgerEntry> _entryBySeq;

  /// The pair-atomic group of [recordId]: an assistant tool-call carrier
  /// plus every result answering its calls (D6 — all or none).
  Set<String> groupOf(String recordId) =>
      _groupByRecordId[recordId] ?? {recordId};

  /// The entry with numeric alias [seq], or `null` (issue #1499: a map
  /// lookup — the linear scan over all entries showed up on judge-pick
  /// validation over marathon sessions).
  LedgerEntry? entryAtSeq(int seq) => _entryBySeq[seq];

  /// The judge input cap (issue #541): the newest [judgePreviewEntries]
  /// entries render. The judge prompt stays O(bounded) regardless of
  /// session size, so the per-call budget (issue #515) stays winnable on
  /// marathon sessions instead of growing into a guaranteed timeout.
  static const int judgePreviewEntries = 512;

  /// Renders the ledger as the judge's input block: at most
  /// [maxEntries] NEWEST entries, preceded by one summary line for the
  /// omitted older prefix (issue #541 — the judge decides on a bounded
  /// preview, not the whole chronicle).
  String render({int maxEntries = judgePreviewEntries}) {
    if (entries.length <= maxEntries) {
      return [for (final entry in entries) _line(entry)].join('\n');
    }
    final omitted = entries.length - maxEntries;
    var omittedTokens = 0;
    for (final entry in entries.take(omitted)) {
      omittedTokens += entry.tokens;
    }
    final head =
        '[…] $omitted older records (seqs ${entries.first.seq}-'
        '${entries[omitted - 1].seq}, ~$omittedTokens tok) are omitted '
        'from this preview — decide on the newest records below';
    return [
      head,
      for (final entry in entries.skip(omitted)) _line(entry),
    ].join('\n');
  }

  String _line(LedgerEntry entry) {
    final kind = entry.kind;
    final exempt = entry.exempt ? '·exempt' : '';
    final detail = entry.preview.isEmpty ? '' : ' · ${entry.preview}';
    return '[${entry.seq}] $kind$exempt ~${entry.tokens}tok$detail';
  }
}

/// Memoizes the derived ledger scalars of records across
/// [buildContextLedger] rebuilds (issue #1499).
///
/// Every compaction pass rebuilds the ledger over the whole visible path,
/// and the expensive part of each entry — token estimation, preview
/// flattening, the synthetic-user scan — scales with the record's CONTENT.
/// On a marathon session that is history re-processed from scratch on
/// every pass (the 2.0s mean / 58.8s max profile). The session file is
/// append-only and record ids are stable, so those scalars never change
/// for a given id: computing them once per record turns every later
/// rebuild into O(changed records) plus cheap map hits.
///
/// OWNERSHIP: one cache per ledger-rebuilding chain, scoped to ONE
/// session — a [StructuredCompactor] instance (one compaction run), a
/// [CompactExpandController] instance (one agent; cleared when the live
/// session object changes). Never share a cache across sessions and never
/// make it global: ids are only unique within a session.
final class LedgerEntryCache {
  final Map<String, _CachedEntry> _byId = {};

  /// Forgets every memoized record (session switch).
  void clear() => _byId.clear();
}

/// The id-keyed scalars a rebuilt [LedgerEntry] needs; the rebuilt entry
/// carries the CURRENT record instance so identity stays honest.
final class _CachedEntry {
  const _CachedEntry({
    required this.seq,
    required this.kind,
    required this.tokens,
    required this.preview,
    required this.toolNames,
  });

  final int seq;
  final String kind;
  final int tokens;
  final String preview;
  final String toolNames;
}

/// Builds the ledger over the VISIBLE branch path (post-projection-walk:
/// hidden and checkpoint-covered records already removed).
///
/// [cache] memoizes per-record entry scalars across calls (issue #1499):
/// pass one cache instance to every rebuild of the same session's ledger.
/// Omitted — as by every direct caller and test — the build computes each
/// entry from scratch, byte-identical to the pre-cache shape.
ContextLedger buildContextLedger({
  required List<SessionRecord> visiblePath,
  required RecordSeqIndex seqs,
  LedgerEntryCache? cache,
}) {
  final entries = <LedgerEntry>[];
  for (final record in visiblePath) {
    final entry = _entryFor(record, seqs, cache);
    if (entry != null) entries.add(entry);
  }
  return ContextLedger._(entries, _pairGroups(visiblePath));
}

LedgerEntry? _entryFor(
  SessionRecord record,
  RecordSeqIndex seqs,
  LedgerEntryCache? cache,
) {
  final seq = seqs.seqOf(record.id);
  if (seq == null) return null;
  final cached = cache?._byId[record.id];
  if (cached != null && cached.seq == seq) {
    // Cache hit: scalars reuse, identity fresh. The seq guard makes the
    // cache self-correcting should an id ever move in file order.
    return LedgerEntry._(
      seq: seq,
      recordId: record.id,
      record: record,
      kind: cached.kind,
      tokens: cached.tokens,
      preview: cached.preview,
      toolNames: cached.toolNames,
    );
  }
  final entry = _recordEntry(record, seq);
  if (entry == null) return null;
  cache?._byId[record.id] = _CachedEntry(
    seq: seq,
    kind: entry.kind,
    tokens: entry.tokens,
    preview: entry.preview,
    toolNames: entry.toolNames,
  );
  return entry;
}

/// One projecting record to its ledger line: `null` when the record kind
/// never projects (the ledger lists only model-visible content).
LedgerEntry? _recordEntry(SessionRecord record, int seq) {
  return switch (record) {
    MessageRecord(:final message) => _messageEntry(record, message, seq),
    CustomMessageRecord() => LedgerEntry._(
      seq: seq,
      recordId: record.id,
      record: record,
      kind: 'notice',
      tokens: estimateTokens(
        UserMessage(content: record.content, timestamp: record.timestamp),
      ),
      preview: _clip(_flattenUser(record.content)),
      toolNames: '',
    ),
    CompactCheckpointRecord ckpt => LedgerEntry._(
      seq: seq,
      recordId: record.id,
      record: record,
      kind: 'ckpt',
      tokens: estimateTokens(UserMessage.text(ckpt.text)),
      preview: _clip(ckpt.text),
      toolNames: '',
    ),
    CompactionRecord legacy => LedgerEntry._(
      seq: seq,
      recordId: record.id,
      record: record,
      kind: 'legacy-ckpt',
      tokens: estimateTokens(UserMessage.text(legacy.summary)),
      preview: _clip(legacy.summary),
      toolNames: '',
    ),
    BranchSummaryRecord branch => LedgerEntry._(
      seq: seq,
      recordId: record.id,
      record: record,
      kind: 'branch-summary',
      tokens: branch.summary.isEmpty
          ? 0
          : estimateTokens(UserMessage.text(branch.summary)),
      preview: _clip(branch.summary),
      toolNames: '',
    ),
    _ => null, // Non-projecting records have no ledger line.
  };
}

/// A message-carrying record to its ledger line, or null when the
/// message kind never projects (the ledger lists only model-visible
/// content).
LedgerEntry? _messageEntry(MessageRecord record, Message message, int seq) {
  switch (message) {
    case AssistantMessage assistant:
      final calls = assistant.content.whereType<ToolCall>().toList();
      return LedgerEntry._(
        seq: seq,
        recordId: record.id,
        record: record,
        kind: calls.isEmpty
            ? 'assistant-TEXT'
            : 'assistant-TOOLCALL(${calls.map((c) => c.name).join(',')})',
        tokens: estimateTokens(message),
        preview: _flattenAssistant(assistant),
        toolNames: calls.map((c) => c.name).join(','),
      );
    case ToolResultMessage result:
      return LedgerEntry._(
        seq: seq,
        recordId: record.id,
        record: record,
        kind: 'toolResult(${result.toolName})',
        tokens: estimateTokens(message),
        preview: _flattenBlocks(result.content),
        toolNames: result.toolName,
      );
    case UserMessage user:
      final text = _flattenUser(user.content);
      final synthetic = isSyntheticUserText(text);
      return LedgerEntry._(
        seq: seq,
        recordId: record.id,
        record: record,
        kind: synthetic ? 'notice' : 'user',
        tokens: estimateTokens(message),
        preview: _clip(text),
        toolNames: '',
      );
    default:
      return null;
  }
}

/// Pair-atomic groups over the visible path (D6): each assistant
/// tool-call carrier groups with the results answering its calls.
Map<String, Set<String>> _pairGroups(List<SessionRecord> path) {
  final groups = <String, Set<String>>{};
  final pendingCalls = <String, String>{}; // toolCallId -> carrier record id
  for (final record in path) {
    final message = record is MessageRecord ? record.message : null;
    if (message is AssistantMessage) {
      final calls = message.content.whereType<ToolCall>().toList();
      if (calls.isEmpty) continue;
      final group = {record.id};
      groups[record.id] = group;
      for (final call in calls) {
        pendingCalls[call.id] = record.id;
      }
    } else if (message is ToolResultMessage) {
      final carrierId = pendingCalls[message.toolCallId];
      if (carrierId != null) {
        groups[carrierId]?.add(record.id);
        groups[record.id] = groups[carrierId]!;
      } else {
        // A result whose carrier is off-ledger (older than the visible
        // window): it hides alone, or stays — never blocks its neighbors.
        groups[record.id] = {record.id};
      }
    }
  }
  return groups;
}

String _flattenAssistant(AssistantMessage message) {
  final text = message.content
      .whereType<TextContent>()
      .map((block) => block.text)
      .join(' ');
  return _clip(text);
}

String _flattenUser(Object content) {
  if (content is String) return content;
  return (content as List<Object>)
      .whereType<TextContent>()
      .map((block) => block.text)
      .join(' ');
}

String _flattenBlocks(List<ContentBlock> blocks) {
  return _clip(blocks.whereType<TextContent>().map((b) => b.text).join(' '));
}

String _clip(String text) {
  final flat = text.replaceAll(RegExp(r'\s+'), ' ').trim();
  if (flat.length <= 110) return flat;
  return '${flat.substring(0, 107)}…';
}

/// The live-edge floor shared by every hide path (issue #1379 tier 2):
/// the ids of the newest [protectLastN] ledger entries — the working set
/// no hide may fold, whoever asks (judge picks, deterministic fallback,
/// LRU re-hide, agent hide). The ONE computation; every consumer calls
/// this so the invariant cannot drift between copies.
Set<String> protectedTailIds(ContextLedger ledger, int protectLastN) {
  final start = ledger.entries.length - protectLastN;
  return {
    for (final entry in ledger.entries.skip(start < 0 ? 0 : start))
      entry.recordId,
  };
}

/// Context projection for the structured compaction engine (issue #148).
///
/// The structured state lives in [HiddenRangeRecord] and
/// [CompactCheckpointRecord] records on the branch. This library derives
/// the render-time view — which records are hidden, which ranges are
/// swallowed by which checkpoint — and walks the branch path into the
/// outgoing message list:
///
/// - hidden records render as one-line markers at their original position;
/// - a checkpoint's marker renders in place of the FIRST record it covers,
///   and everything it covers stops rendering individually;
/// - a checkpoint whose own record is covered by a later checkpoint is
///   skipped (nesting, D4);
/// - everything else projects exactly as the classic projection does.
///
/// All state is keyed by stable record ids. The short numeric ids shown to
/// the model are computed here from the append-only file order via
/// [RecordSeqIndex] and never persisted (AC3).
library;

import 'markers.dart';
import '../summary_sanitizer.dart';
import '../token_estimation.dart';
import '../../context.dart';
import '../../types.dart';
import '../../session/session_record.dart';

/// Numeric alias index over a session's stored records.
///
/// The id the model sees for a record is its 1-based JSONL line number
/// (the session header is line 1), so the zero-tool fallback —
/// `read $FAH_SESSION_FILE:<line>` — resolves to the same record. The file
/// is append-only, so a record's alias is stable for the session's
/// lifetime; branches share the numbering because they share the file.
final class RecordSeqIndex {
  /// Creates an index over [entries] in file order.
  RecordSeqIndex(this.entries)
    : _seqById = {
        for (var i = 0; i < entries.length; i++) entries[i].id: i + 2,
      };

  /// All records in file order.
  final List<SessionRecord> entries;

  final Map<String, int> _seqById;

  /// The numeric alias of [recordId], or `null` when unknown.
  int? seqOf(String recordId) => _seqById[recordId];

  /// The record at numeric alias [seq], or `null` when out of range.
  SessionRecord? recordAt(int seq) {
    final i = seq - 2;
    return i >= 0 && i < entries.length ? entries[i] : null;
  }
}

/// Derived, immutable view of the structured state on a branch path.
final class StructuredViewState {
  const StructuredViewState._({
    required this.hiddenRecordIds,
    required this.checkpoints,
    required this.coveredRecordIds,
    this.pinnedRecordIds = const {},
  });

  /// Union of every [HiddenRangeRecord.recordIds] on the path.
  final Set<String> hiddenRecordIds;

  /// Checkpoints on the path, in path order.
  final List<CompactCheckpointRecord> checkpoints;

  /// Record id -> the checkpoint covering it (a later checkpoint wins over
  /// an earlier one for the same record, D4 nesting).
  final Map<String, CompactCheckpointRecord> coveredRecordIds;

  /// Record ids currently pinned (issue #1379 tier 2): never hidden by
  /// judge, fallback, LRU re-hide, or agent hide — never checkpoint-covered.
  final Set<String> pinnedRecordIds;

  /// Whether no structured state exists on the path.
  bool get isEmpty =>
      hiddenRecordIds.length + checkpoints.length + coveredRecordIds.length ==
      0;

  /// Whether [recordId] is swallowed by a checkpoint (hidden-and-covered
  /// counts as covered — the checkpoint's marker owns the position).
  bool isCovered(String recordId) => coveredRecordIds.containsKey(recordId);
}

/// One fold record the replay dropped WHOLE (gh-1425 AC2): it carries NO
/// ids this build can read — the version-skew shape (an older writer put
/// the ids under keys this binary does not parse, so every id field is
/// empty). All-or-note resolution means none of its ids enter the derived
/// state (there are none) and its own marker/text never renders; a visible
/// note names the dropped generation instead.
final class DroppedFold {
  const DroppedFold({required this.record});

  /// The fold record itself (hidden range / compact checkpoint /
  /// segment pin).
  final SessionRecord record;
}

/// The [StructuredViewState] a fold-aware replay produced plus the folds
/// it had to drop whole.
final class ResolvedFolds {
  const ResolvedFolds({required this.state, required this.dropped});

  final StructuredViewState state;

  /// The dropped fold records, in path order — the renderer surfaces one
  /// visible resume note per entry.
  final List<DroppedFold> dropped;
}

/// Resolves the structured fold chain over a branch [path] with ALL-OR-NOTE
/// semantics (gh-1425 AC2): a fold record the replaying binary cannot
/// RESOLVE — it carries no ids at all (the record-shape skew a newer binary
/// can hit replaying an older build's folds: the ids live under keys this
/// build does not read) — is dropped WHOLE and reported, so its text never
/// renders as a valid checkpoint/hide and nothing half-applies silently.
///
/// References that merely point OFF the path are NOT skew and are applied
/// as before, unchanged: a checkpoint legitimately covers an off-branch
/// arc (it still renders its summary in place), and a hidden range may span
/// below a windowed resume's resident window (hiding those is moot — the
/// seq alias keeps the exempt classification quiet under a classic
/// boundary, issue #266 F1a). Both rendered identically before this
/// resolver existed (REG-1).
ResolvedFolds resolveStructuredFolds(List<SessionRecord> path) {
  final hidden = <String>{};
  final checkpoints = <CompactCheckpointRecord>[];
  final covered = <String, CompactCheckpointRecord>{};
  final pinnedIds = <String>{};
  final dropped = <DroppedFold>[];
  void apply(
    SessionRecord record,
    bool emptyShape,
    void Function() applyEffect,
  ) {
    if (emptyShape) {
      dropped.add(DroppedFold(record: record));
      return;
    }
    applyEffect();
  }

  for (final record in path) {
    switch (record) {
      case HiddenRangeRecord(:final recordIds):
        apply(
          record,
          recordIds.where((id) => id.isNotEmpty).isEmpty,
          () => hidden.addAll(recordIds),
        );
      case SegmentPinRecord(:final recordIds, :final pinned):
        apply(record, recordIds.where((id) => id.isNotEmpty).isEmpty, () {
          pinned ? pinnedIds.addAll(recordIds) : pinnedIds.removeAll(recordIds);
        });
      case CompactCheckpointRecord checkpoint:
        apply(
          record,
          checkpoint.coversRecordIds.where((id) => id.isNotEmpty).isEmpty &&
              checkpoint.firstRecordId.isEmpty &&
              checkpoint.lastRecordId.isEmpty,
          () {
            checkpoints.add(checkpoint);
            for (final id in checkpoint.coversRecordIds) {
              covered[id] = checkpoint;
            }
            // The range itself is swallowed even when covers is partial.
            covered[checkpoint.firstRecordId] = checkpoint;
            covered[checkpoint.lastRecordId] = checkpoint;
          },
        );
      default:
        break;
    }
  }
  return ResolvedFolds(
    state: StructuredViewState._(
      hiddenRecordIds: hidden,
      checkpoints: checkpoints,
      coveredRecordIds: covered,
      pinnedRecordIds: pinnedIds,
    ),
    dropped: dropped,
  );
}

/// Derives the structured view over a branch [path] (post-classic-transform).
StructuredViewState buildStructuredViewState(List<SessionRecord> path) {
  final hidden = <String>{};
  final checkpoints = <CompactCheckpointRecord>[];
  final covered = <String, CompactCheckpointRecord>{};
  final pinnedRecordIds = <String>{};
  for (final record in path) {
    switch (record) {
      case HiddenRangeRecord(:final recordIds):
        hidden.addAll(recordIds);
      case SegmentPinRecord(:final recordIds, :final pinned):
        pinned
            ? pinnedRecordIds.addAll(recordIds)
            : pinnedRecordIds.removeAll(recordIds);
      case CompactCheckpointRecord():
        checkpoints.add(record);
        for (final id in record.coversRecordIds) {
          covered[id] = record;
        }
        // The range itself is swallowed even when covers is partial.
        covered[record.firstRecordId] = record;
        covered[record.lastRecordId] = record;
      default:
        break;
    }
  }
  return StructuredViewState._(
    hiddenRecordIds: hidden,
    checkpoints: checkpoints,
    coveredRecordIds: covered,
    pinnedRecordIds: pinnedRecordIds,
  );
}

/// The model-visible projecting records over a transformed path — the
/// population both the judge ledger and the agent-hide validation work
/// over (issue #1379 tier 2: one convention, engine and tool alike).
List<SessionRecord> visibleStructuredPath(
  List<SessionRecord> path,
  StructuredViewState state,
) => [
  for (final record in path)
    if (!state.isCovered(record.id) &&
        record is! HiddenRangeRecord &&
        !state.hiddenRecordIds.contains(record.id) &&
        projectsStructured(record))
      record,
];

/// Whether [record] renders into the model context at all.
bool projectsStructured(SessionRecord record) =>
    record is MessageRecord ||
    record is CustomMessageRecord ||
    record is CompactionRecord ||
    record is BranchSummaryRecord ||
    record is CompactCheckpointRecord;

/// Renders [path] into the outgoing message list with markers.
///
/// [projectEntry] is the classic per-record projection (the session tree's
/// `_entryToMessages`); structured records never reach it. The result is
/// wire-safe by construction: hidden tool results stay tool results, and
/// hidden assistant carriers become plain user-role markers, so no tool
/// call is ever orphaned (issue #85).
///
/// The fold chain resolves with ALL-OR-NOTE semantics (gh-1425 AC2): a
/// fold record the replaying binary cannot resolve — it carries no ids at
/// all (an older build's shape: the ids live under keys this build does
/// not read) — is dropped whole and a visible `[resume]` note renders at
/// its position naming the dropped generation. References that merely
/// point off the path (off-branch checkpoint coverage, below-window
/// ranges) are not skew and apply unchanged.
List<Message> renderStructuredMessages({
  required List<SessionRecord> path,
  required RecordSeqIndex seqs,
  required List<Message> Function(SessionRecord record) projectEntry,
}) {
  final resolution = resolveStructuredFolds(path);
  final state = resolution.state;
  final droppedById = {
    for (final drop in resolution.dropped) drop.record.id: drop,
  };
  final byId = {for (final record in path) record.id: record};
  // Tool calls whose assistant carrier is itself hidden: hiding the
  // carrier downgrades its results to user-role markers too, or the wire
  // would carry tool_results whose tool_use no longer exists (the #85
  // orphan bug wearing a marker).
  final hiddenCallIds = _hiddenToolCallIds(path, state);
  final messages = <Message>[];
  final emitted = <String>{};
  for (final record in path) {
    final drop = droppedById[record.id];
    if (drop != null) {
      // The dropped fold's own marker/text never renders — the note
      // replaces it and the span it named renders unfolded.
      messages.add(_droppedFoldNote(drop, seqs));
      continue;
    }
    messages.addAll(
      _projectRecord(
        record,
        state: state,
        byId: byId,
        seqs: seqs,
        emitted: emitted,
        hiddenCallIds: hiddenCallIds,
        projectEntry: projectEntry,
      ),
    );
  }
  return messages;
}

/// The visible resume note for a dropped fold (gh-1425 AC2): names the
/// dropped generation — fold kind, file position, why it dropped — so a
/// version-skewed fold can never vanish silently. Plain text, one wire
/// message at the fold's position.
Message _droppedFoldNote(DroppedFold drop, RecordSeqIndex seqs) {
  final record = drop.record;
  final seq = seqs.seqOf(record.id);
  final kind = switch (record) {
    HiddenRangeRecord() => 'hidden_range',
    CompactCheckpointRecord() => 'compact_checkpoint',
    SegmentPinRecord() => 'segment_pin',
    _ => record.type,
  };
  return UserMessage.text(
    '[resume] structured fold #${seq ?? '?'} ($kind) dropped: it carries '
    'no record ids (a shape an older build wrote — the fields this build '
    'reads are empty) — its span renders unfolded and no part of the fold '
    'was applied. The session file keeps every record.',
    timestamp: record.timestamp,
  );
}

/// Tool-call ids on hidden (or checkpoint-covered) assistant carriers —
/// their results are orphaned the moment the carrier leaves the wire.
Set<String> _hiddenToolCallIds(
  List<SessionRecord> path,
  StructuredViewState state,
) {
  final callIds = <String>{};
  for (final record in path) {
    final message = record is MessageRecord ? record.message : null;
    if (message is AssistantMessage &&
        (state.hiddenRecordIds.contains(record.id) ||
            state.isCovered(record.id))) {
      for (final block in message.content) {
        if (block is ToolCall) callIds.add(block.id);
      }
    }
  }
  return callIds;
}

/// One path record to its wire messages.
List<Message> _projectRecord(
  SessionRecord record, {
  required StructuredViewState state,
  required Map<String, SessionRecord> byId,
  required RecordSeqIndex seqs,
  required Set<String> emitted,
  required Set<String> hiddenCallIds,
  required List<Message> Function(SessionRecord record) projectEntry,
}) {
  // A covering checkpoint renders at the position of its first visible
  // path record (D2: markers sit where the content sat); null when the
  // record is not covered (or its checkpoint was itself hidden — then
  // the range renders as if uncovered).
  final covered = _coverAt(
    record,
    state: state,
    byId: byId,
    seqs: seqs,
    emitted: emitted,
  );
  if (covered != null) return covered;
  switch (record) {
    case HiddenRangeRecord():
      return const [];
    case CompactCheckpointRecord():
      // Renders in place only when its range sits fully off-branch
      // (nothing visible triggered the in-place emission above). A judge
      // hide targets the checkpoint itself: no marker, no swallow.
      if (state.hiddenRecordIds.contains(record.id)) return const [];
      return emitted.add(record.id)
          ? [_checkpointMessage(record, byId: byId, seqs: seqs, state: state)]
          : const [];
    case MessageRecord():
      return [
        _messageAt(
          record,
          state: state,
          seqs: seqs,
          hiddenCallIds: hiddenCallIds,
        ),
      ];
    case CompactionRecord() || BranchSummaryRecord():
      return _legacyAt(
        record,
        state: state,
        seqs: seqs,
        projectEntry: projectEntry,
      );
    case CustomMessageRecord():
      return _customAt(
        record,
        state: state,
        seqs: seqs,
        projectEntry: projectEntry,
      );
    default:
      return const [];
  }
}

/// The covering-checkpoint projection for [record], or null when it does
/// not apply (not covered, or the covering checkpoint is itself hidden).
List<Message>? _coverAt(
  SessionRecord record, {
  required StructuredViewState state,
  required Map<String, SessionRecord> byId,
  required RecordSeqIndex seqs,
  required Set<String> emitted,
}) {
  final cover = state.coveredRecordIds[record.id];
  if (cover == null || state.hiddenRecordIds.contains(cover.id)) return null;
  return emitted.add(cover.id) && !state.isCovered(cover.id)
      ? [_checkpointMessage(cover, byId: byId, seqs: seqs, state: state)]
      : const [];
}

/// A [CustomMessageRecord] to its wire message: host-injected context
/// must never silently vanish on a structured branch — hidden customs
/// render as notice markers, visible ones project through the classic
/// per-record projection.
List<Message> _customAt(
  CustomMessageRecord record, {
  required StructuredViewState state,
  required RecordSeqIndex seqs,
  required List<Message> Function(SessionRecord record) projectEntry,
}) {
  if (!state.hiddenRecordIds.contains(record.id)) return projectEntry(record);
  return [
    UserMessage(
      content: hiddenMarker(
        seq: seqs.seqOf(record.id) ?? 0,
        kind: markerKinds.notice,
        tokens: recordTokens(record),
      ),
      timestamp: record.timestamp,
    ),
  ];
}

/// A [MessageRecord] to its wire message: hidden and orphaned records
/// become markers, everything else passes through untouched.
Message _messageAt(
  MessageRecord record, {
  required StructuredViewState state,
  required RecordSeqIndex seqs,
  required Set<String> hiddenCallIds,
}) {
  final message = record.message;
  final seq = seqs.seqOf(record.id);
  final hidden = state.hiddenRecordIds.contains(record.id) && seq != null;
  // A visible result whose call was hidden or swallowed by a
  // checkpoint cannot stay a tool_result on the wire — it renders
  // as a user-role marker (its content stays expandable).
  final orphaned =
      message is ToolResultMessage &&
      hiddenCallIds.contains(message.toolCallId);
  return hidden || orphaned
      ? _hiddenMessage(
          record,
          message,
          seq ?? 0,
          orphaned: orphaned,
          pinned: state.pinnedRecordIds.contains(record.id),
        )
      : message;
}

/// A classic compaction or branch-summary record: hidden → marker,
/// visible → the classic projection.
List<Message> _legacyAt(
  SessionRecord record, {
  required StructuredViewState state,
  required RecordSeqIndex seqs,
  required List<Message> Function(SessionRecord record) projectEntry,
}) {
  final seq = seqs.seqOf(record.id);
  if (state.hiddenRecordIds.contains(record.id) && seq != null) {
    return [
      UserMessage.text(
        hiddenMarker(
          seq: seq,
          kind: markerKindFor(record),
          tokens: recordTokens(record),
          preview: markerPreview(recordPreviewSource(record)),
        ),
        timestamp: record.timestamp,
      ),
    ];
  }
  return projectEntry(record);
}

Message _checkpointMessage(
  CompactCheckpointRecord record, {
  required StructuredViewState state,
  required Map<String, SessionRecord> byId,
  required RecordSeqIndex seqs,
}) {
  final startSeq = seqs.seqOf(record.firstRecordId) ?? 0;
  final endSeq = seqs.seqOf(record.lastRecordId) ?? startSeq;
  final covers = <int>[];
  for (final id in record.coversRecordIds) {
    final seq = seqs.seqOf(id);
    if (seq != null) covers.add(seq);
  }
  var coveredTokens = 0;
  for (final id in record.coversRecordIds) {
    final covered = byId[id];
    if (covered != null) coveredTokens += recordTokens(covered);
  }
  // Issue #1131: sanitize once — the header's token estimate must describe
  // the text actually rendered, not the raw (possibly poisoned) record.
  final text = sanitizeSummary(record.text).text;
  final header = checkpointMarkerHeader(
    startSeq: startSeq,
    endSeq: endSeq,
    coveredTokens: coveredTokens,
    textTokens: estimateTokens(UserMessage.text(text)),
    coversRanges: idsToRanges(covers),
  );
  final index = hiddenIndexSection([
    // Consolidated markers (issue #387) are not re-listed: a checkpoint
    // over a marker run would otherwise reproduce every marker line
    // inside itself and never shrink. The header's covers ranges keep
    // every id expandable.
    for (final id in record.coversRecordIds)
      if (!state.hiddenRecordIds.contains(id)) ?byId[id],
  ], seqs);
  return UserMessage.text('$header\n$text$index', timestamp: record.timestamp);
}

/// Builds the marker replacement for a hidden [MessageRecord].
Message _hiddenMessage(
  MessageRecord record,
  Message message,
  int seq, {
  required bool orphaned,
  required bool pinned,
}) {
  final preview = markerPreview(recordPreviewSource(record));
  switch (message) {
    case ToolResultMessage() when !orphaned:
      // Keep the pair on the wire: same call id, same tool name, marker
      // as the only content.
      return ToolResultMessage(
        toolCallId: message.toolCallId,
        toolName: message.toolName,
        content: [
          TextContent(
            text: hiddenMarker(
              seq: seq,
              kind: markerKinds.toolResult,
              tokens: estimateTokens(message),
              preview: preview,
              pinned: pinned,
            ),
          ),
        ],
        isError: message.isError,
        timestamp: message.timestamp,
      );
    case ToolResultMessage():
      // Carrier hidden too: a tool_result without its tool_use is an
      // invalid request — downgrade to a plain user-role marker.
      return UserMessage.text(
        hiddenMarker(
          seq: seq,
          kind: markerKinds.toolResult,
          tokens: estimateTokens(message),
          preview: preview,
          pinned: pinned,
        ),
        timestamp: message.timestamp,
      );
    case AssistantMessage():
      return UserMessage.text(
        hiddenMarker(
          seq: seq,
          kind: markerKinds.assistant,
          tokens: estimateTokens(message),
          preview: preview,
          pinned: pinned,
        ),
        timestamp: message.timestamp,
      );
    default:
      return UserMessage.text(
        hiddenMarker(
          seq: seq,
          kind: markerKinds.user,
          tokens: estimateTokens(message),
          preview: preview,
          pinned: pinned,
        ),
        timestamp: message.timestamp,
      );
  }
}

/// The kind label a record shows in markers and the hidden-segment index.
String markerKindFor(SessionRecord record) => switch (record) {
  MessageRecord(:final message) => switch (message) {
    UserMessage() => markerKinds.user,
    AssistantMessage() => markerKinds.assistant,
    ToolResultMessage() => markerKinds.toolResult,
    _ => message.role,
  },
  CustomMessageRecord() => markerKinds.notice,
  CompactCheckpointRecord() => markerKinds.checkpoint,
  CompactionRecord() => markerKinds.legacyCheckpoint,
  BranchSummaryRecord() => markerKinds.branchSummary,
  _ => 'system',
};

/// The flat text a record's preview draws from — the record's own
/// content, wrapper stripped. Image blocks collapse to their kind-named
/// placeholder (E3), so a preview never carries base64.
String recordPreviewSource(SessionRecord record) => switch (record) {
  MessageRecord(:final message) => switch (message) {
    UserMessage(:final content) => _previewUserText(content),
    ToolResultMessage(:final content) => _previewBlocks(content),
    AssistantMessage(:final content) => _previewBlocks(content),
    _ => message.role,
  },
  CustomMessageRecord(:final content) => _previewUserText(content),
  CompactCheckpointRecord(:final text) => text,
  CompactionRecord(:final summary) => summary,
  BranchSummaryRecord(:final summary) => summary,
  _ => '',
};

String _previewUserText(Object content) =>
    content is String ? content : _previewBlocks(content as List<ContentBlock>);

String _previewBlocks(List<ContentBlock> blocks) => [
  for (final block in blocks)
    switch (block) {
      TextContent(:final text) => text,
      ImageContent(:final mimeType) => imagePreview(mimeType),
      _ => '[${block.runtimeType}]',
    },
].join('\n');

/// The hidden-segments index heading the agent consults (issue #266 F1a).
const hiddenIndexHeading = 'hidden segments (compact_expand reopens any id):';

/// One marker line per [records] — id, kind, size, preview — appended
/// under a summary so history folded away stays consultable and
/// expandable. Empty string when nothing survives resolution.
String hiddenIndexSection(
  Iterable<SessionRecord> records,
  RecordSeqIndex seqs,
) {
  final lines = <String>[];
  for (final record in records) {
    final seq = seqs.seqOf(record.id);
    if (seq == null) continue;
    lines.add(
      hiddenMarker(
        seq: seq,
        kind: markerKindFor(record),
        tokens: recordTokens(record),
        preview: markerPreview(recordPreviewSource(record)),
      ),
    );
  }
  return lines.isEmpty ? '' : '\n\n$hiddenIndexHeading\n${lines.join('\n')}';
}

int recordTokens(SessionRecord record) {
  switch (record) {
    case MessageRecord(:final message):
      return estimateTokens(message);
    case CustomMessageRecord(:final content):
      return estimateTokens(
        UserMessage(
          content: content,
          timestamp: DateTime.fromMillisecondsSinceEpoch(0),
        ),
      );
    case CompactCheckpointRecord(:final text):
      return estimateTokens(UserMessage.text(text));
    case CompactionRecord(:final summary):
      return estimateTokens(UserMessage.text(summary));
    case BranchSummaryRecord(:final summary):
      return estimateTokens(UserMessage.text(summary));
    default:
      return 0;
  }
}

/// The projected wire cost of one hidden record (issue #387): its
/// one-line marker message — the marker is what rides the wire after a
/// hide pass, so checkpoint selection weighs hidden records at the
/// marker size, not the original payload size.
int hiddenMarkerTokens(SessionRecord record, int seq) => estimateTokens(
  UserMessage.text(
    hiddenMarker(
      seq: seq,
      kind: markerKindFor(record),
      tokens: recordTokens(record),
      preview: markerPreview(recordPreviewSource(record)),
    ),
  ),
);

/// The `compact_expand` tool (issue #148 D3, agent UX #266): pulls a
/// hidden or compacted context segment back into the conversation by its
/// numeric marker id — and, with no `target`, surfaces what is hidden at
/// all.
///
/// Context markers (`[3:hidden·tool_result·4.2k·"first line…"]`,
/// `[2-6:ckpt·38k→40tok·covers:3,5]`) are render-time projections — the
/// underlying records stay in the session file. With a `target` the tool
/// resolves the marker's numeric id (or range) through [RecordSeqIndex]
/// and returns the original content with the record wrapper stripped,
/// paged for giant segments and capped by a per-turn expand budget (Q6:
/// 32k tokens/turn); every success states the budget left. Only hidden /
/// checkpoint-covered / summary-folded records expand — a visible record
/// is told apart honestly (one message per failure class, #266 F2).
///
/// With no `target` the tool returns the hidden-segment index (id, kind,
/// size, preview, page count); a `query` filters and ranks it, scanning
/// hidden content too (F1b). Discovery never consumes the budget.
///
/// The session file never changes: expanded content enters context as a
/// normal tool result and may be re-hidden by the next pressure event.
/// The zero-tool fallback — `read $FAH_SESSION_FILE:<line>` — resolves
/// the same records raw.
library;

import '../../agent/agent.dart' show Agent;
import '../../agent/agent_loop.dart'
    show AgentEvent, MessageStartEvent, ToolExecutionResult, ToolUpdateCallback;
import '../../agent/agent_tool.dart';
import '../../approval/approval.dart' show ApprovalTier;
import '../../cancel_token.dart' show CancelToken;
import '../../context.dart';
import '../../prompts/prompts.g.dart' show compactExpandToolDescriptionPrompt;
import '../../session/session_record.dart';
import '../../session/session_tree.dart' show Session;
import '../../types.dart';
import 'engine.dart' show classicTransform, refreshAgentState;
import '../compaction.dart' show isSyntheticUserText;
import 'judge.dart' show hideProtectTailEntries;
import 'ledger.dart';
import 'markers.dart'
    show formatMarkerTokens, hiddenMarker, idsToRanges, markerPreview;
import 'projection.dart'
    show
        RecordSeqIndex,
        buildStructuredViewState,
        hiddenIndexHeading,
        markerKindFor,
        recordPreviewSource,
        recordTokens,
        visibleStructuredPath;

// ignore_for_file: prefer_initializing_formals

/// The `compact_expand` tool name.
const compactExpandToolName = 'compact_expand';

/// Per-turn expand budget in (estimated) tokens (Q6 proposal, pinned).
const defaultExpandTurnBudgetTokens = 32 * 1024;

/// Characters per page: ~24k tokens at the chars/4 heuristic, past the
/// `read` tool's 50 KB cap so a giant segment pages instead of truncating.
const defaultExpandPageChars = 96 * 1024;

/// Index rows returned per discovery call before the agent is told to
/// narrow with `query` (# ponytail: fixed cap; raise when sessions hide
/// thousands of segments routinely).
const maxDiscoverRows = 200;

/// The production chars/4 heuristic (see `token_estimation.dart`).
int _tokensForChars(int chars) => chars ~/ 4;

/// Extracts the numeric id or range from a marker or bare target:
/// `5`, `2-6`, or a pasted `[5:hidden·tool_result·4.5k]`.
final RegExp _targetPattern = RegExp(r'(\d+)(?:-(\d+))?');

/// One honest message per failure class (issue #266 F2 / AC3) — the
/// exact strings `UT-msgs` snapshot-pins. One fact, one phrasing.

/// Out of range: `no record 1 — valid ids 2-2397`.
String expandNoRecordMsg(String label, String validIds) =>
    'no record $label — valid ids $validIds';

/// Target exists but renders in context: nothing to reopen.
String expandVisibleMsg(String label) =>
    'record $label is visible, nothing to expand';

/// Hide-state or system record with no expandable text.
String expandNoContentMsg(String label) =>
    'record $label carries no content to expand';

/// Per-turn budget spent (#266 F2: the reset is part of the fact).
String expandBudgetMsg(int budgetTokens) =>
    'expand budget exhausted for this turn '
    '(${budgetTokens ~/ 1024}k tokens) — it resets on the next user turn';

/// Remaining per-turn budget appended to every SUCCESS response (AC3):
/// `expand budget left: ~18k tokens`.
String expandBudgetLeft(int remainingTokens) => remainingTokens >= 1024
    ? 'expand budget left: ~${remainingTokens ~/ 1024}k tokens'
    : 'expand budget left: ~$remainingTokens tokens';

/// The valid-id range over a session's file order (`2-2397`): the header
/// is line 1, records are lines 2..N+1.
String expandValidIds(int entryCount) =>
    entryCount == 0 ? 'none (session is empty)' : '2-${entryCount + 1}';

/// Owns the per-turn expand budget and the [compact_expand] tool for one
/// agent. Created next to [builtinTools] (see [CheckpointRewindController]);
/// the budget resets when a new user turn starts.
final class CompactExpandController {
  /// Creates the controller and attaches the turn-reset listener to
  /// [agent]. [session] resolves the LIVE session per call — hosts switch
  /// sessions without rebuilding the tool surface.
  CompactExpandController({
    required Agent agent,
    required this.session,
    this.turnBudgetTokens = defaultExpandTurnBudgetTokens,
    this.pageChars = defaultExpandPageChars,
  }) : _agent = agent {
    _unsubscribe = _agent.subscribe(_onAgentEvent);
  }

  final Agent _agent;
  final Session? Function() session;
  final int turnBudgetTokens;
  final int pageChars;
  int _spentTokens = 0;
  void Function()? _unsubscribe;

  /// Issue #1499: ledger entry memo for the hide action's rebuilds — one
  /// controller lives for one agent, so the memo survives across turns.
  final LedgerEntryCache _ledgerCache = LedgerEntryCache();

  /// The [Session] instance the memo was built against: hosts switch
  /// sessions under a live controller, and ids are only unique within a
  /// session — a switch invalidates every memoized record.
  Session? _ledgerCacheSession;

  /// The `compact_expand` tool bound to this controller.
  late final AgentTool tool = AgentTool(
    name: compactExpandToolName,
    description: compactExpandToolDescriptionPrompt,
    tier: ApprovalTier.read,
    parameters: const {
      'type': 'object',
      'properties': {
        'target': {
          'type': 'string',
          'description':
              'Numeric id or range from a context marker, '
              'e.g. "5" or "2-6". Omit to list the hidden-segment index.',
        },
        'action': {
          'type': 'string',
          'description':
              'Tier 2 segment management (issue #1379). With a target: '
              '"hide" folds a dead-weight segment into its expandable '
              'marker right now, without waiting for pressure; "pin" '
              'shields a segment from every hide/compact path; "unpin" '
              'releases it. Omit to expand the target.',
        },
        'query': {
          'type': 'string',
          'description':
              'Search the hidden segments (preview and full content) when '
              'you know WHAT you need but not the id. Free — no budget.',
        },
        'page': {
          'type': 'integer',
          'description': '1-based page for giant segments (default 1)',
          'minimum': 1,
        },
      },
      'required': [],
    },
    execute: _execute,
  );

  /// Tokens spent on expands this turn so far.
  int get spentTokens => _spentTokens;

  /// Detaches from the agent.
  void dispose() {
    _unsubscribe?.call();
    _unsubscribe = null;
  }

  Future<void> _onAgentEvent(AgentEvent event, CancelToken cancelToken) async {
    // A new user turn opens a fresh budget (Q6: per-TURN).
    if (event is MessageStartEvent && event.message is UserMessage) {
      _spentTokens = 0;
    }
  }

  Future<ToolExecutionResult> _execute(
    Map<String, dynamic> args,
    CancelToken? cancelToken,
    ToolUpdateCallback? onUpdate,
  ) async {
    final live = session();
    if (live == null) {
      return ToolExecutionResult.text('no active session to expand from');
    }
    final entries = await live.getEntries();
    final seqs = RecordSeqIndex(entries);
    final validIds = expandValidIds(entries.length);

    final action = (args['action'] as String?)?.trim();
    if (action != null && action.isNotEmpty) {
      return _segmentAction(live, seqs, validIds, action, args['target']);
    }

    final (range, parseError) = _parseRangeArg(args['target']);
    if (parseError != null) return ToolExecutionResult.text(parseError);
    if (range == null) {
      // Discovery is free (AC2): the index never consumes the budget.
      return ToolExecutionResult.text(
        await _discover(live, seqs, validIds, query: args['query'] as String?),
      );
    }

    final (expandable, _) = await _expandabilityOf(live);
    final (blocks, skipped, blocked, label) = _gatherBlocks(
      seqs,
      range.$1,
      range.$2,
      (record) => expandable(record.id),
    );
    if (blocks.isEmpty) {
      return ToolExecutionResult.text(
        _emptyReason(skipped, blocked, label, validIds),
      );
    }
    return _paged(args, blocks, skipped, blocked, label);
  }

  /// Tier 2 (issue #1379): agent-initiated hide / pin / unpin over the
  /// same validated surface the judge hides through — ids exist, pairs
  /// snap whole, pins and the protected tail hold — but every rejection
  /// is a structured error, never a silent narrowing (AC1).
  Future<ToolExecutionResult> _segmentAction(
    Session live,
    RecordSeqIndex seqs,
    String validIds,
    String action,
    Object? rawTarget,
  ) async {
    final unknown = _unknownActionError(action);
    if (unknown != null) return unknown;
    final (target, targetError) = _actionTarget(action, rawTarget);
    if (targetError != null) return targetError;
    final (start, end, label) = target!;
    final (targets, resolveError) = _resolveRangeTargets(
      seqs,
      start,
      end,
      label,
      validIds,
    );
    if (resolveError != null) return resolveError;
    // Real user turns are exempt from every path (F8) — say so instead
    // of silently no-oping.
    final pinning = action == 'pin' || action == 'unpin';
    final userTurnError = _realUserTurnRejection(targets, label, pinning);
    if (userTurnError != null) return userTurnError;
    if (pinning) return _pinAction(live, targets, label, action == 'pin');
    return _hideAction(live, seqs, targets, label);
  }

  /// The structured rejection for an unrecognized action name (AC1) —
  /// null when [action] is one of "hide", "pin", "unpin".
  ToolExecutionResult? _unknownActionError(String action) {
    final pinning = action == 'pin' || action == 'unpin';
    if (!pinning && action != 'hide') {
      return ToolExecutionResult.text(
        'unknown action "$action" — use "hide", "pin" or "unpin"',
      );
    }
    return null;
  }

  /// The validated target of a segment action, flattened to
  /// `(start, end, label)` — or the structured rejection: an unparsable
  /// target names the parse error, a missing target asks for one (AC1).
  ((int, int, String)?, ToolExecutionResult?) _actionTarget(
    String action,
    Object? rawTarget,
  ) {
    final (range, parseError) = _parseRangeArg(rawTarget);
    if (parseError != null) {
      return (null, ToolExecutionResult.text(parseError));
    }
    if (range == null) {
      return (
        null,
        ToolExecutionResult.text(
          'action "$action" requires a target id or range',
        ),
      );
    }
    return ((range.$1, range.$2, _rangeLabel(range.$1, range.$2)), null);
  }

  /// The target records of the validated seq range in order — or the
  /// structured rejection when a seq has no record (AC1). The records
  /// companion is unused whenever the error is non-null.
  (List<SessionRecord>, ToolExecutionResult?) _resolveRangeTargets(
    RecordSeqIndex seqs,
    int start,
    int end,
    String label,
    String validIds,
  ) {
    final targets = <SessionRecord>[];
    for (var seq = start; seq <= end; seq++) {
      final record = seqs.recordAt(seq);
      if (record == null) {
        return (
          targets,
          ToolExecutionResult.text(expandNoRecordMsg(label, validIds)),
        );
      }
      targets.add(record);
    }
    return (targets, null);
  }

  /// The structured rejection when any target is a real user turn (F8:
  /// exempt from every path) — say so instead of silently no-oping.
  /// Null when none is.
  ToolExecutionResult? _realUserTurnRejection(
    List<SessionRecord> targets,
    String label,
    bool pinning,
  ) {
    for (final record in targets) {
      if (record is MessageRecord && _realUserTurn(record)) {
        return ToolExecutionResult.text(
          'records $label are real user turns — always exempt, '
          '${pinning ? 'pinning changes nothing' : 'never hidden'}',
        );
      }
    }
    return null;
  }

  /// Pin / unpin: appends a [SegmentPinRecord] (replay: last one wins).
  Future<ToolExecutionResult> _pinAction(
    Session live,
    List<SessionRecord> targets,
    String label,
    bool pinned,
  ) async {
    final viewState = buildStructuredViewState(
      classicTransform(await live.getBranch()),
    );
    final allSet = targets.every(
      (record) => viewState.pinnedRecordIds.contains(record.id) == pinned,
    );
    if (allSet) {
      return ToolExecutionResult.text(
        pinned
            ? 'records $label are already pinned'
            : 'records $label are not pinned',
      );
    }
    await live.appendSegmentPin(
      recordIds: [for (final record in targets) record.id]..sort(),
      pinned: pinned,
    );
    return ToolExecutionResult.text(
      pinned
          ? 'pinned records $label — judge, pressure, LRU re-hide and '
                'compact_expand hide can no longer touch them'
          : 'unpinned records $label — hide and compaction may process '
                'them again',
    );
  }

  /// The memo for [live]'s ledger rebuilds — cleared when the live
  /// session object changed since the last call (issue #1499: record ids
  /// are unique within a session only).
  LedgerEntryCache _ledgerCacheFor(Session live) {
    if (!identical(live, _ledgerCacheSession)) {
      _ledgerCacheSession = live;
      _ledgerCache.clear();
    }
    return _ledgerCache;
  }

  /// The agent-initiated hide (AC1): the engine's validation class,
  /// structured errors, then a state refresh so the very next request of
  /// this turn renders the new markers (the host's per-message
  /// persistence keeps session and state in sync — the same contract the
  /// engine's state refresh relies on).
  Future<ToolExecutionResult> _hideAction(
    Session live,
    RecordSeqIndex seqs,
    List<SessionRecord> targets,
    String label,
  ) async {
    final path = classicTransform(await live.getBranch());
    final viewState = buildStructuredViewState(path);
    final pathIds = {for (final record in path) record.id};
    for (final record in targets) {
      if (!pathIds.contains(record.id)) {
        return ToolExecutionResult.text(
          'records $label are off the active branch — nothing to hide',
        );
      }
    }
    final visibleTargets = [
      for (final record in targets)
        if (!viewState.hiddenRecordIds.contains(record.id)) record,
    ];
    if (visibleTargets.isEmpty) {
      return ToolExecutionResult.text('records $label are already hidden');
    }
    final ledger = buildContextLedger(
      visiblePath: visibleStructuredPath(path, viewState),
      seqs: seqs,
      cache: _ledgerCacheFor(live),
    );
    final protectedTail = protectedTailIds(ledger, hideProtectTailEntries);
    // Whole pair groups or never (D6 / #85): the hide snaps OUTWARD, and
    // any group member in the protected tail or pinned set vetoes the
    // whole ask with one honest message.
    final ids = <String>{};
    for (final record in visibleTargets) {
      final group = ledger.groupOf(record.id);
      for (final id in group) {
        if (protectedTail.contains(id)) {
          return ToolExecutionResult.text(
            'records $label touch the protected recent tail '
            '(last $hideProtectTailEntries entries) — not hidden',
          );
        }
        if (viewState.pinnedRecordIds.contains(id)) {
          return ToolExecutionResult.text(
            'records $label are pinned — unpin first (action "unpin")',
          );
        }
      }
      ids.addAll(group);
    }
    var freedTokens = 0;
    for (final id in ids) {
      final seq = seqs.seqOf(id);
      if (seq != null) freedTokens += ledger.entryAtSeq(seq)?.tokens ?? 0;
    }
    await live.appendHiddenRange(recordIds: ids.toList()..sort());
    await refreshAgentState(live, _agent.state);
    final seqsOf = [for (final id in ids) seqs.seqOf(id) ?? 0]..sort();
    final groupLabel = _rangeLabel(seqsOf.first, seqsOf.last);
    return ToolExecutionResult.text(
      'hid records $groupLabel (~${formatMarkerTokens(freedTokens)}tok) — '
      'they render as markers now; compact_expand reopens them',
    );
  }

  /// Whether [record] is a real user turn (F8 exempt): a UserMessage
  /// whose content is not a synthetic system marker. Block-list content
  /// is never synthetic — always a real user turn.
  bool _realUserTurn(MessageRecord record) {
    final message = record.message;
    if (message is! UserMessage) return false;
    final content = message.content;
    return content is! String || !isSyntheticUserText(content);
  }

  /// Parses + validates the `target` arg: `(null, null)` = discovery mode,
  /// `(range, null)` = expand mode, `(_, error)` = honest failure.
  ((int, int)?, String?) _parseRangeArg(Object? rawTarget) {
    final range = rawTarget == null ? null : _parseTarget(rawTarget);
    if (rawTarget != null && range == null) {
      return (
        null,
        'target must be a numeric id or range from a marker, '
            'e.g. "5" or "2-6" (got: $rawTarget)',
      );
    }
    if (range == null) return (null, null);
    final (start, end) = range;
    if (end < start) {
      return (null, 'inverted range $start-$end — use "min-max"');
    }
    return (range, null);
  }

  /// The F2 predicate: hidden, checkpoint-covered, folded away by a
  /// classic summary, or off-branch → expandable (visible is not).
  /// The F2 predicate (expandable ids) plus the pinned id set — discovery
  /// marks pinned rows and hides must never target them (issue #1379
  /// tier 2).
  Future<(bool Function(String id), Set<String>)> _expandabilityOf(
    Session live,
  ) async {
    final path = classicTransform(await live.getBranch());
    final state = buildStructuredViewState(path);
    final pathIds = {for (final record in path) record.id};
    bool expandable(String id) =>
        !pathIds.contains(id) ||
        state.hiddenRecordIds.contains(id) ||
        state.isCovered(id);
    return (expandable, state.pinnedRecordIds);
  }

  /// One honest message per empty-gather failure class (AC3).
  String _emptyReason(
    List<int> skipped,
    List<int> blocked,
    String label,
    String validIds,
  ) {
    if (skipped.isNotEmpty) return expandNoRecordMsg(label, validIds);
    if (blocked.isNotEmpty) return expandVisibleMsg(label);
    return expandNoContentMsg(label);
  }

  /// Validates the page arg, charges the delivered page against the
  /// per-turn budget (S6), and renders header + slice + paging footer.
  ToolExecutionResult _paged(
    Map<String, dynamic> args,
    List<String> blocks,
    List<int> skipped,
    List<int> blocked,
    String label,
  ) {
    final content = blocks.join('\n\n');
    final pages = (content.length / pageChars).ceil();
    final page = (args['page'] as num?)?.toInt() ?? 1;
    if (page < 1 || page > pages) {
      return ToolExecutionResult.text(
        'page $page out of range (1-$pages) for target $label',
      );
    }
    final slice = _pageSlice(content, page, pages, pageChars);
    // Budget charges the DELIVERED page, not the whole segment: paging a
    // 20 MB record through the turn must stay possible — the sum over all
    // pages converges to the segment cost (S6).
    final cost = _tokensForChars(slice.length + 1);
    if (_spentTokens + cost > turnBudgetTokens) {
      return ToolExecutionResult.text(expandBudgetMsg(turnBudgetTokens));
    }
    _spentTokens += cost;
    return ToolExecutionResult.text(
      '${_header(label, skipped, blocked)}\n$slice${_footer(label, page, pages)}',
    );
  }

  String _header(String label, List<int> skipped, List<int> blocked) {
    final header = StringBuffer('[expand $label');
    if (skipped.isNotEmpty) {
      header.write(' · out of range: ${idsToRanges(skipped)}');
    }
    if (blocked.isNotEmpty) {
      header.write(' · visible: ${idsToRanges(blocked)}');
    }
    header.write(' · ${expandBudgetLeft(turnBudgetTokens - _spentTokens)}]');
    return header.toString();
  }

  String _footer(String label, int page, int pages) {
    if (pages <= 1) return '';
    if (page < pages) {
      return '\n\n[page $page/$pages — continue with compact_expand '
          '{"target": "$label", "page": ${page + 1}}]';
    }
    return '\n\n[end of record $label]';
  }

  /// The hidden-segment index (no `target`), optionally filtered and
  /// ranked by [query] (F1b): preview/kind hits rank above content hits.
  Future<String> _discover(
    Session live,
    RecordSeqIndex seqs,
    String validIds, {
    String? query,
  }) async {
    final (expandable, pinnedIds) = await _expandabilityOf(live);
    final rows = <(int, int, String)>[];
    for (var seq = 2; seq <= seqs.entries.length + 1; seq++) {
      final record = seqs.recordAt(seq)!;
      if (!expandable(record.id)) continue; // renders in context
      final row = _discoverRow(
        seq,
        record,
        query,
        pinned: pinnedIds.contains(record.id),
      );
      if (row != null) rows.add(row);
    }
    // seq is the tiebreak so equal ranks stay in file order regardless
    // of sort stability.
    rows.sort((a, b) => a.$1 != b.$1 ? b.$1 - a.$1 : a.$2 - b.$2);
    return _formatIndex(rows, query, validIds);
  }

  /// `(rank, seq, marker)` for one hidden segment; null when [query]
  /// filters it out.
  (int, int, String)? _discoverRow(
    int seq,
    SessionRecord record,
    String? query, {
    required bool pinned,
  }) {
    final content = recordPreviewSource(record);
    final block = _renderRecord(seq, record) ?? content;
    final pages = (block.length / pageChars).ceil();
    final preview = markerPreview(content);
    final rank = _rank(preview, content, markerKindFor(record), query);
    if (rank == 0) return null;
    var marker = hiddenMarker(
      seq: seq,
      kind: markerKindFor(record),
      tokens: recordTokens(record),
      preview: preview,
      pinned: pinned,
    );
    if (pages > 1) {
      marker = '${marker.substring(0, marker.length - 1)}·pages:$pages]';
    }
    return (rank, seq, marker);
  }

  int _rank(String preview, String content, String kind, String? query) {
    final needle = query?.toLowerCase();
    if (needle == null) return 1;
    if (preview.toLowerCase().contains(needle) || kind.contains(needle)) {
      return 2;
    }
    if (content.toLowerCase().contains(needle)) return 1;
    return 0;
  }

  String _formatIndex(
    List<(int, int, String)> rows,
    String? query,
    String validIds,
  ) {
    if (query == null) {
      if (rows.isEmpty) {
        return 'no hidden segments — everything in this session is visible '
            'in context';
      }
      return '$hiddenIndexHeading\n${_topRows(rows)}';
    }
    if (rows.isEmpty) {
      return 'no hidden segments match "$query" — valid ids $validIds '
          '(drop query for the full index)';
    }
    return '${rows.length} hidden segments match "$query" (best first):\n'
        '${_topRows(rows, hint: 'narrow query')}';
  }

  String _topRows(
    List<(int, int, String)> rows, {
    String hint = 'narrow with query',
  }) {
    final lines = [for (final row in rows.take(maxDiscoverRows)) row.$3];
    if (rows.length > maxDiscoverRows) {
      lines.add('…and ${rows.length - maxDiscoverRows} more — $hint');
    }
    return lines.join('\n');
  }
}

/// Parses the target arg (`5`, `2-6`, or a pasted marker) into its
/// inclusive id range; null when no numeric target is present.
(int, int)? _parseTarget(Object? raw) {
  final match = _targetPattern.firstMatch('$raw');
  if (match == null) return null;
  final start = int.parse(match.group(1)!);
  final end = match.group(2) == null ? start : int.parse(match.group(2)!);
  return (start, end);
}

/// Renders every expandable record in `start..end`; ids with no record
/// land in `skipped`, visible ids in `blocked` — each feeds its honest
/// failure class or success note.
(List<String>, List<int>, List<int>, String) _gatherBlocks(
  RecordSeqIndex seqs,
  int start,
  int end,
  bool Function(SessionRecord) expandable,
) {
  final blocks = <String>[];
  final skipped = <int>[];
  final blocked = <int>[];
  for (var seq = start; seq <= end; seq++) {
    final record = seqs.recordAt(seq);
    if (record == null) {
      skipped.add(seq);
      continue;
    }
    if (record is HiddenRangeRecord) {
      continue; // pure hide state — the ids it names expand directly
    }
    if (!expandable(record)) {
      blocked.add(seq);
      continue;
    }
    final block = _renderRecord(seq, record);
    if (block != null) blocks.add(block);
  }
  return (blocks, skipped, blocked, _rangeLabel(start, end));
}

/// `'5'` or `'2-6'` — the range label used in every expand string.
String _rangeLabel(int start, int end) =>
    start == end ? '$start' : '$start-$end';

/// The 1-based [page] slice of a paged segment (the whole content when
/// it fits one page).
String _pageSlice(String content, int page, int pages, int pageChars) =>
    pages == 1
    ? content
    : content.substring(
        (page - 1) * pageChars,
        page == pages ? content.length : page * pageChars,
      );

/// Renders one record's clean content (the record wrapper stripped), or
/// null for pure state records ([HiddenRangeRecord]) that carry none.
String? _renderRecord(int seq, SessionRecord record) {
  switch (record) {
    case MessageRecord(:final message):
      return _renderMessageRecord(seq, message);
    case CustomMessageRecord(:final content):
      return '[$seq context]\n${_userText(content)}';
    case CompactCheckpointRecord(:final text, :final coversRecordIds):
      return '[$seq ckpt · covers ${coversRecordIds.length} ids]\n$text';
    case CompactionRecord(:final summary):
      return '[$seq legacy-ckpt · classic · not-expandable]\n$summary';
    case BranchSummaryRecord(:final summary):
      return summary.isEmpty ? null : '[$seq branch-summary]\n$summary';
    case HiddenRangeRecord():
      return null; // Pure hide state — the records it names expand directly.
    default:
      return '[$seq ${record.runtimeType}]\n(system record — no content)';
  }
}

/// The message-record half of [_renderRecord]: user text, the assistant
/// render, tool results, and the role-name fallback for any other role.
String _renderMessageRecord(int seq, Message message) => switch (message) {
  UserMessage() => '[$seq user]\n${_userText(message.content)}',
  AssistantMessage() => '[$seq assistant]\n${_assistantText(message)}',
  ToolResultMessage(:final toolName, :final content) =>
    '[$seq tool_result · $toolName]\n${_blockTexts(content)}',
  _ => '[$seq ${message.role}]',
};

String _userText(Object content) =>
    content is String ? content : _blockTexts(content as List<ContentBlock>);

String _assistantText(AssistantMessage message) {
  final parts = <String>[];
  for (final block in message.content) {
    switch (block) {
      case TextContent(:final text):
        parts.add(text);
      case ThinkingContent(:final thinking):
        parts.add('<thinking>\n$thinking\n</thinking>');
      case ToolCall(:final name, :final arguments):
        parts.add('tool_call $name(${_shortArgs(arguments)})');
      case ImageContent():
        parts.add('[image]');
      case AudioContent():
        parts.add('[audio]');
      case VideoContent():
        parts.add('[video]');
    }
  }
  return parts.join('\n');
}

String _blockTexts(List<ContentBlock> blocks) => [
  for (final block in blocks)
    switch (block) {
      TextContent(:final text) => text,
      ImageContent() => '[image]',
      _ => '[${block.runtimeType}]',
    },
].join('\n');

String _shortArgs(Map<String, dynamic> arguments) {
  const cap = 200;
  final text = arguments.toString();
  return text.length <= cap ? text : '${text.substring(0, cap)}…';
}

