      CompactionRecord(:final summary, :final timestamp) => [
        UserMessage.text(
          '$compactionSummaryPrefix'
          '${sanitizeSummary(summary).text}'
          '$compactionSummarySuffix'
          '${_classicHiddenIndex(classicHidden, seqs)}',
